/* data/maulid/diba.js - Maulid Diba'i (Arab, transliterasi, terjemah). Dibuat oleh template-kitab/maulid_dari_md.py.
   Satu bait = {no, ar, lt, id}. Boleh diedit langsung. */
registerMaulid({"id": "diba", "judul": "Maulid Diba'i", "sumber": "Maulid Ad-Diba'i, karya Imam 'Abdurrahman Ad-Diba'i (w. 944 H). Teks Arab disalin ulang dari scan PDF; transliterasi & terjemah disusun ulang - mohon ditashih.",bagian:[
{judul:"Pembuka: Ya Rabbi Shalli 'ala Muhammad",isi:[
{"ar": "يَا رَبِّ صَلِّ عَلَى مُحَمَّدْ ۞ يَا رَبِّ صَلِّ عَلَيْهِ وَسَلِّمْ", "lt": "Yâ rabbi shalli ‘alâ muḥammad ۞ yâ rabbi shalli ‘alaihi wa sallim", "id": "Ya Tuhanku, limpahkanlah rahmat kepada Nabi Muhammad; ya Tuhanku, limpahkanlah rahmat dan salam kepadanya.", "no": 1},
{"ar": "يَا رَبِّ بَلِّغْهُ الْوَسِيْلَةْ ۞ يَا رَبِّ خُصَّهُ بِالْفَضِيْلَةْ", "lt": "Yâ rabbi ballighhul-wasîlah ۞ yâ rabbi khush-shahu bil-fadlîlah", "id": "Ya Tuhanku, sampaikanlah beliau pada derajat wasilah; ya Tuhanku, istimewakanlah beliau dengan keutamaan.", "no": 2},
{"ar": "يَا رَبِّ وَارْضَ عَنِ الصَّحَابَةْ ۞ يَا رَبِّ وَارْضَ عَنِ السُّلَالَةْ", "lt": "Yâ rabbi wardla ‘anish-shaḥâbah ۞ yâ rabbi wardla ‘anis-sulâlah", "id": "Ya Tuhanku, ridailah para sahabat; ya Tuhanku, ridailah anak keturunan beliau.", "no": 3},
{"ar": "يَا رَبِّ وَارْضَ عَنِ الْمَشَايِخْ ۞ يَا رَبِّ فَارْحَمْ وَالِدِيْنَا", "lt": "Yâ rabbi wardla ‘anil-masyâyikh ۞ yâ rabbi farḥam wâlidînâ", "id": "Ya Tuhanku, ridailah para guru; ya Tuhanku, rahmatilah kedua orang tua kami.", "no": 4},
{"ar": "يَا رَبِّ وَارْحَمْنَا جَمِيْعًا ۞ يَا رَبِّ وَارْحَمْ كُلَّ مُسْلِمْ", "lt": "Yâ rabbi warḥamnâ jamî‘an ۞ yâ rabbi warḥam kulla muslim", "id": "Ya Tuhanku, rahmatilah kami semua; ya Tuhanku, rahmatilah setiap muslim.", "no": 5},
{"ar": "يَا رَبِّ وَاغْفِرْ لِكُلِّ مُذْنِبْ ۞ يَا رَبِّ لَا تَقْطَعْ رَجَانَا", "lt": "Yâ rabbi waghfir likulli mudznib ۞ yâ rabbi lâ taqṭa‘ rajânâ", "id": "Ya Tuhanku, ampunilah setiap orang yang berdosa; ya Tuhanku, jangan Engkau putuskan harapan kami.", "no": 6},
{"ar": "يَا رَبِّ يَا سَامِعْ دُعَانَا ۞ يَا رَبِّ بَلِّغْنَا نَزُوْرُهْ", "lt": "Yâ rabbi yâ sâmi‘ du‘ânâ ۞ yâ rabbi ballighnâ nazûruh", "id": "Ya Tuhanku, wahai Yang Maha Mendengar doa kami; ya Tuhanku, sampaikanlah kami untuk berziarah kepadanya.", "no": 7},
{"ar": "يَا رَبِّ تَغْشَانَا بِنُوْرِهْ ۞ يَا رَبِّ حِفْظَانَكْ وَأَمَانَكْ", "lt": "Yâ rabbi taghsyânâ binûrih ۞ yâ rabbi ḥifdhânak wa amânak", "id": "Ya Tuhanku, liputilah kami dengan cahayanya; ya Tuhanku, (berilah kami) penjagaan dan perlindungan-Mu.", "no": 8},
{"ar": "يَا رَبِّ وَاسْكِنَّا جِنَانَكْ ۞ يَا رَبِّ أَجِرْنَا مِنْ عَذَابِكْ", "lt": "Yâ rabbi wa askinnâ jinânak ۞ yâ rabbi ajirnâ min ‘adzâbik", "id": "Ya Tuhanku, tempatkanlah kami di surga-surga-Mu; ya Tuhanku, selamatkanlah kami dari azab-Mu.", "no": 9},
{"ar": "يَا رَبِّ وَارْزُقْنَا الشَّهَادَةْ ۞ يَا رَبِّ حِطْنَا بِالسَّعَادَةْ", "lt": "Yâ rabbi warzuqnasy-syahâdah ۞ yâ rabbi ḥuṭnâ bis-sa‘âdah", "id": "Ya Tuhanku, karuniakanlah kami mati syahid; ya Tuhanku, liputilah kami dengan kebahagiaan.", "no": 10},
{"ar": "يَا رَبِّ وَاصْلِحْ كُلَّ مُصْلِحْ ۞ يَا رَبِّ وَاكْفِ كُلَّ مُؤْذِيْ", "lt": "Yâ rabbi wa ashliḥ kulla mushliḥ ۞ yâ rabbi wakfi kulla mu'dzî", "id": "Ya Tuhanku, perbaikilah setiap orang yang berbuat kebaikan; ya Tuhanku, lindungilah kami dari setiap orang yang menyakiti.", "no": 11},
{"ar": "يَا رَبِّ نَخْتِمْ بِالْمُشَفَّعْ ۞ يَا رَبِّ صَلِّ عَلَيْهِ وَسَلِّمْ", "lt": "Yâ rabbi nakhtim bil-musyaffa‘ ۞ yâ rabbi shalli ‘alaihi wa sallim", "id": "Ya Tuhanku, kami tutup dengan (menyebut) Nabi yang diterima syafaatnya; ya Tuhanku, limpahkanlah rahmat dan salam kepadanya.", "no": 12},
{"ar": "بِسْمِ اللهِ الرَّحْمٰنِ الرَّحِيْمِ", "lt": "Bismillâhir-raḥmânir-raḥîm", "id": "Dengan nama Allah Yang Maha Pengasih lagi Maha Penyayang.", "no": 13},
{"ar": "لَقَدْ جَاءَكُمْ رَسُوْلٌ مِّنْ أَنْفُسِكُمْ عَزِيْزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيْصٌ عَلَيْكُمْ بِالْمُؤْمِنِيْنَ رَءُوْفٌ رَّحِيْمٌ", "lt": "Laqad jâ'akum rasûlum min anfusikum ‘azîzun ‘alaihi mâ ‘anittum ḥarîshun ‘alaikum bil-mu'minîna ra'ûfur raḥîm", "id": "Sungguh telah datang kepadamu seorang rasul dari kaummu sendiri; berat terasa olehnya penderitaanmu, ia sangat menginginkan (keimanan dan keselamatan) bagimu, amat belas kasih lagi penyayang terhadap orang-orang mukmin. (QS. At-Taubah: 128)", "no": 14},
{"ar": "إِنَّ اللهَ وَمَلَائِكَتَهُ يُصَلُّوْنَ عَلَى النَّبِيِّ يَا أَيُّهَا الَّذِيْنَ آمَنُوْا صَلُّوْا عَلَيْهِ وَسَلِّمُوْا تَسْلِيْمًا", "lt": "Innallâha wa malâ'ikatahû yushallûna ‘alan-nabiyy, yâ ayyuhal-ladzîna âmanû shallû ‘alaihi wa sallimû taslîmâ", "id": "Sesungguhnya Allah dan para malaikat-Nya bershalawat untuk Nabi. Wahai orang-orang yang beriman, bershalawatlah kamu untuknya dan ucapkanlah salam dengan penuh penghormatan. (QS. Al-Ahzab: 56)", "no": 15},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 16}]},
{judul:"Ya Rasulallah Salamun 'Alaik",isi:[
{"ar": "يَا رَسُوْلَ اللهِ سَلَامٌ عَلَيْكْ ۞ يَا رَفِيْعَ الشَّانِ وَالدَّرَجِ", "lt": "Yâ rasûlallâh salâmun ‘alaik ۞ yâ rafî‘asy-syâni wad-daraji", "id": "Wahai Rasulullah, salam sejahtera untukmu; wahai yang luhur martabat dan derajatnya.", "no": 1},
{"ar": "عَطْفَةً يَا جِيْرَةَ الْعَلَمِ ۞ يَا أُهَيْلَ الْجُوْدِ وَالْكَرَمِ", "lt": "‘Aṭfatan yâ jîratal-‘alami ۞ yâ uhailal-jûdi wal-karami", "id": "Kasihanilah kami, wahai penduduk tanah suci; wahai keluarga yang penuh kedermawanan dan kemuliaan.", "no": 2},
{"ar": "نَحْنُ جِيْرَانٌ بِذَا الْحَرَمِ ۞ حَرَمِ الْإِحْسَانِ وَالْحَسَنِ", "lt": "Naḥnu jîrânun bidzal-ḥarami ۞ ḥaramil-iḥsâni wal-ḥasani", "id": "Kami adalah tetangga di tanah haram ini, tanah haram kebaikan dan keindahan.", "no": 3},
{"ar": "نَحْنُ مِنْ قَوْمٍ بِهِ سَكَنُوْا ۞ وَبِهِ مِنْ خَوْفِهِمْ أَمِنُوْا", "lt": "Naḥnu min qaumin bihî sakanû ۞ wa bihî min khaufihim aminû", "id": "Kami dari kaum yang bermukim di sana, dan dengannya mereka aman dari ketakutan.", "no": 4},
{"ar": "وَبِآيَاتِ الْقُرْآنِ عُنُوْا ۞ فَاتَّئِدْ فِيْنَا أَخَا الْوَهَنِ", "lt": "Wa bi'âyâtil-qur'âni ‘unû ۞ fatta'id fînâ akhal-wahani", "id": "Mereka tekun mengamalkan ayat-ayat Al-Qur'an; maka tenanglah engkau bersama kami, wahai yang lemah.", "no": 5},
{"ar": "نَعْرِفُ الْبَطْحَا وَتَعْرِفُنَا ۞ وَالصَّفَا وَالْبَيْتُ يَأْلَفُنَا", "lt": "Na‘riful-baṭḥâ wa ta‘rifunâ ۞ wash-shafâ wal-baitu ya'lafunâ", "id": "Kami mengenal Bathha' (Makkah) dan ia pun mengenal kami; bukit Shafa dan Baitullah pun akrab dengan kami.", "no": 6},
{"ar": "وَلَنَا الْمَعْلَى وَخَيْفُ مِنًى ۞ فَاعْلَمَنْ هٰذَا وَكُنْ زَكِنِ", "lt": "Wa lanal-ma‘lâ wa khaifu minan ۞ fa‘laman hâdzâ wa kun zakini", "id": "Milik kami pula Ma‘la dan Khaif di Mina; ketahuilah ini dan jadilah orang yang paham.", "no": 7},
{"ar": "وَلَنَا خَيْرُ الْأَنَامِ أَبُ ۞ وَعَلِيُّ الْمُرْتَضٰى حَسَبُ", "lt": "Wa lanâ khairul-anâmi abun ۞ wa ‘aliyyul-murtadlâ ḥasabun", "id": "Kami memiliki leluhur sebaik-baik manusia, dan Ali Al-Murtadha sebagai kemuliaan nasab kami.", "no": 8},
{"ar": "وَإِلَى السِّبْطَيْنِ نَنْتَسِبُ ۞ نَسَبًا مَا فِيْهِ مِنْ دَخَنِ", "lt": "Wa ilas-sibṭaini nantasibu ۞ nasaban mâ fîhi min dakhani", "id": "Kepada kedua cucu (Hasan dan Husain) kami bernasab, nasab yang tak bernoda sedikit pun.", "no": 9},
{"ar": "كَمْ إِمَامٍ بَعْدَهُ خَلَفُوْا ۞ مِنْهُ سَادَاتٌ بِذَا عُرِفُوْا", "lt": "Kam imâmin ba‘dahû khalafû ۞ minhu sâdâtun bidzâ ‘urifû", "id": "Betapa banyak imam penerus sesudahnya; dari mereka lahir para sayyid yang dikenal dengan (kemuliaan) ini.", "no": 10},
{"ar": "وَبِهٰذَا الْوَصْفِ قَدْ وُصِفُوْا ۞ مِنْ قَدِيْمِ الدَّهْرِ وَالزَّمَنِ", "lt": "Wa bihâdzal-washfi qad wushifû ۞ min qadîmid-dahri waz-zamani", "id": "Dengan sifat inilah mereka disifati sejak masa yang lampau.", "no": 11},
{"ar": "مِثْلُ زَيْنِ الْعَابِدِيْنَ عَلِيْ ۞ وَابْنِهِ الْبَاقِرِ خَيْرِ وَلِيْ", "lt": "Mitslu zainil-‘âbidîna ‘alî ۞ wabnihil-bâqiri khairi walî", "id": "Seperti Ali Zainal Abidin dan putranya Al-Baqir, sebaik-baik wali.", "no": 12},
{"ar": "وَالْإِمَامِ الصَّادِقِ الْحَفِلِ ۞ وَعَلِيٍّ ذِي الْعُلَا الْيَقِنِ", "lt": "Wal-imâmish-shâdiqil-ḥafili ۞ wa ‘aliyyin dzil-‘ulal-yaqini", "id": "Dan Imam Ja‘far Ash-Shadiq yang agung, serta Ali yang luhur lagi penuh keyakinan.", "no": 13},
{"ar": "فَهُمُ الْقَوْمُ الَّذِيْنَ هُدُوْا ۞ وَبِفَضْلِ اللهِ قَدْ سَعِدُوْا", "lt": "Fahumul-qaumul-ladzîna hudû ۞ wa bifadllillâhi qad sa‘idû", "id": "Merekalah kaum yang mendapat petunjuk, dan dengan karunia Allah mereka berbahagia.", "no": 14},
{"ar": "وَلِغَيْرِ اللهِ مَا قَصَدُوْا ۞ وَمَعَ الْقُرْآنِ فِيْ قَرَنِ", "lt": "Wa lighairillâhi mâ qashadû ۞ wa ma‘al-qur'âni fî qarani", "id": "Mereka tidak bertujuan kepada selain Allah, dan mereka senantiasa bersama Al-Qur'an.", "no": 15},
{"ar": "أَهْلُ بَيْتِ الْمُصْطَفَى الطُّهُرِ ۞ هُمْ أَمَانُ الْأَرْضِ فَادَّكِرِ", "lt": "Ahlu baitil-mushṭafaṭ-ṭuhuri ۞ hum amânul-ardli faddakiri", "id": "Ahlul bait Nabi pilihan yang suci, merekalah pengaman bumi; maka ingatlah.", "no": 16},
{"ar": "شُبِّهُوْا بِالْأَنْجُمِ الزُّهُرِ ۞ مِثْلَ مَا قَدْ جَاءَ فِي السُّنَنِ", "lt": "Syubbihû bil-anjumiz-zuhuri ۞ mitsla mâ qad jâ'a fis-sunani", "id": "Mereka diibaratkan bintang-bintang yang bersinar, sebagaimana tersebut dalam hadis-hadis.", "no": 17},
{"ar": "وَسَفِيْنٌ لِلنَّجَاةِ إِذَا ۞ خِفْتَ مِنْ طُوْفَانِ كُلِّ أَذٰى", "lt": "Wa safînun lin-najâti idzâ ۞ khifta min ṭûfâni kulli adzâ", "id": "Mereka bagaikan bahtera keselamatan, bila engkau takut akan banjir segala bencana.", "no": 18},
{"ar": "فَانْجُ فِيْهَا لَا تَكُوْنُ كَذَا ۞ وَاعْتَصِمْ بِاللهِ وَاسْتَعِنِ", "lt": "Fanju fîhâ lâ takûnu kadzâ ۞ wa‘tashim billâhi wasta‘ini", "id": "Maka selamatlah dengan menaikinya, jangan sampai tertinggal; berpegang teguhlah kepada Allah dan mohonlah pertolongan.", "no": 19},
{"ar": "رَبِّ فَانْفَعْنَا بِبَرْكَتِهِمْ ۞ وَاهْدِنَا الْحُسْنٰى بِحُرْمَتِهِمْ", "lt": "Rabbi fanfa‘nâ bibarkatihim ۞ wahdinal-ḥusnâ biḥurmatihim", "id": "Wahai Tuhanku, berilah kami manfaat dengan berkah mereka, dan tunjukilah kami kebaikan demi kehormatan mereka.", "no": 20},
{"ar": "وَأَمِتْنَا فِيْ طَرِيْقَتِهِمْ ۞ وَمُعَافَاةٍ مِنَ الْفِتَنِ", "lt": "Wa amitnâ fî ṭarîqatihim ۞ wa mu‘âfâtin minal-fitani", "id": "Matikanlah kami di atas jalan mereka, dalam keadaan selamat dari segala fitnah.", "no": 21},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 22}]},
{judul:"Al-Hamdu Lillahil Qawiyyil Ghalib",isi:[
{"ar": "بِسْمِ اللهِ الرَّحْمٰنِ الرَّحِيْمِ", "lt": "Bismillâhir-raḥmânir-raḥîm", "id": "Dengan nama Allah Yang Maha Pengasih lagi Maha Penyayang.", "no": 1},
{"ar": "اَلْحَمْدُ لِلّٰهِ الْقَوِيِّ الْغَالِبِ، الْوَلِيِّ الطَّالِبِ، الْبَاعِثِ الْوَارِثِ الْمَانِحِ السَّالِبِ، عَالِمِ الْكَائِنِ وَالْبَائِنِ وَالزَّائِلِ وَالذَّاهِبِ", "lt": "Al-ḥamdu lillâhil-qawiyyil-ghâlib, al-waliyyiṭ-ṭâlib, al-bâ‘itsil-wâritsil-mâniḥis-sâlib, ‘âlimil-kâ'ini wal-bâ'ini waz-zâ'ili wadz-dzâhib", "id": "Segala puji bagi Allah Yang Mahakuat lagi Mahaperkasa, Maha Pelindung lagi Maha Menuntut, Yang membangkitkan, Yang mewarisi, Yang memberi dan Yang mencabut, Yang mengetahui yang ada dan yang tampak, yang sirna dan yang berlalu.", "no": 2},
{"ar": "يُسَبِّحُهُ الْآفِلُ وَالْمَائِلُ وَالطَّالِعُ وَالْغَارِبُ، وَيُوَحِّدُهُ النَّاطِقُ وَالصَّامِتُ وَالْجَامِدُ وَالذَّائِبُ، يَضْرِبُ بِعَدْلِهِ السَّاكِنُ وَيَسْكُنُ بِفَضْلِهِ الضَّارِبُ", "lt": "Yusabbiḥuhul-âfilu wal-mâ'ilu waṭ-ṭâli‘u wal-ghârib, wa yuwaḥḥiduhun-nâṭiqu wash-shâmitu wal-jâmidu wadz-dzâ'ib, yadlribu bi‘adlihis-sâkinu wa yaskunu bifadllihidl-dlârib", "id": "Bertasbih kepada-Nya yang terbenam dan yang condong, yang terbit dan yang tenggelam; mengesakan-Nya yang berbicara dan yang diam, yang beku dan yang cair. Dengan keadilan-Nya yang diam pun bergerak, dan dengan karunia-Nya yang bergerak pun menjadi tenang.", "no": 3},
{"ar": "(لَا إِلٰهَ إِلَّا اللهُ) حَكِيْمٌ أَظْهَرَ بَدِيْعَ حِكَمِهِ وَالْعَجَائِبَ، فِيْ تَرْتِيْبِ تَرْكِيْبِ هٰذِهِ الْقَوَالِبِ", "lt": "(Lâ ilâha illallâh) ḥakîmun adh-hara badî‘a ḥikamihî wal-‘ajâ'ib, fî tartîbi tarkîbi hâdzihil-qawâlib", "id": "(Tiada tuhan selain Allah) Yang Mahabijaksana, yang menampakkan keindahan hikmah dan keajaiban-Nya dalam susunan rangka tubuh-tubuh ini.", "no": 4},
{"ar": "خَلَقَ مُخًّا وَعَظْمًا وَعَصَبًا وَعُرُوْقًا وَلَحْمًا وَجِلْدًا وَشَعْرًا بِنَظْمٍ مُؤْتَلِفٍ مُتَرَاكِبٍ، مِنْ مَاءٍ دَافِقٍ يَخْرُجُ مِنْ بَيْنِ الصُّلْبِ وَالتَّرَائِبِ", "lt": "Khalaqa mukhkhan wa ‘adhman wa ‘ashaban wa ‘urûqan wa laḥman wa jildan wa sya‘ran, binadhmin mu'talifin mutarâkib, min mâ'in dâfiqin yakhruju min bainish-shulbi wat-tarâ'ib", "id": "Dia menciptakan sumsum, tulang, urat saraf, pembuluh darah, daging, kulit, dan rambut dalam susunan yang serasi dan bertumpuk, dari air yang memancar, yang keluar dari antara tulang sulbi dan tulang dada.", "no": 5},
{"ar": "(لَا إِلٰهَ إِلَّا اللهُ) كَرِيْمٌ بَسَطَ لِخَلْقِهِ بِسَاطَ كَرَمِهِ وَالْمَوَاهِبِ، يَنْزِلُ فِيْ كُلِّ لَيْلَةٍ إِلَى سَمَاءِ الدُّنْيَا وَيُنَادِيْ: هَلْ مِنْ مُسْتَغْفِرٍ؟ هَلْ مِنْ تَائِبٍ؟ هَلْ مِنْ طَالِبِ حَاجَةٍ فَأُنِيْلَهُ الْمَطَالِبَ؟", "lt": "(Lâ ilâha illallâh) karîmun basaṭa likhalqihî bisâṭa karamihî wal-mawâhib, yanzilu fî kulli lailatin ilâ samâ'id-dunyâ wa yunâdî: hal min mustaghfir? hal min tâ'ib? hal min ṭâlibi ḥâjatin fa unîlahul-maṭâlib?", "id": "(Tiada tuhan selain Allah) Yang Mahamulia, yang membentangkan hamparan kemurahan dan anugerah-Nya bagi makhluk-Nya. Setiap malam (rahmat-Nya) turun ke langit dunia dan menyeru: Adakah yang memohon ampun? Adakah yang bertobat? Adakah yang meminta hajat, agar Aku kabulkan permintaannya?", "no": 6},
{"ar": "فَلَوْ رَأَيْتَ الْخُدَّامَ قِيَامًا عَلَى الْأَقْدَامِ وَقَدْ جَادُوْا بِالدُّمُوْعِ السَّوَاكِبِ، وَالْقَوْمُ بَيْنَ نَادِمٍ وَتَائِبٍ، وَخَائِفٍ لِنَفْسِهِ يُعَاتِبُ، وَآبِقٍ مِنَ الذُّنُوْبِ إِلَيْهِ هَارِبٍ", "lt": "Falau ra'aital-khuddâma qiyâman ‘alal-aqdâmi wa qad jâdû bid-dumû‘is-sawâkib, wal-qaumu baina nâdimin wa tâ'ib, wa khâ'ifin linafsihî yu‘âtib, wa âbiqin minadz-dzunûbi ilaihi hârib", "id": "Andai engkau melihat para hamba yang berdiri di atas kaki mereka dengan air mata bercucuran; sebagian menyesal dan bertobat, sebagian takut dan mencela dirinya sendiri, dan sebagian lari dari dosa-dosanya menuju kepada-Nya.", "no": 7},
{"ar": "فَلَا يَزَالُوْنَ فِي الْاِسْتِغْفَارِ حَتّٰى يَكُفَّ كَفُّ النَّهَارِ ذُيُوْلَ الْغَيَاهِبِ، فَيَعُوْدُوْنَ وَقَدْ فَازُوْا بِالْمَطْلُوْبِ، وَأَدْرَكُوْا رِضَا الْمَحْبُوْبِ، وَلَمْ يَعُدْ أَحَدٌ مِنَ الْقَوْمِ وَهُوَ خَائِبٌ", "lt": "Falâ yazâlûna fil-istighfâri ḥattâ yakuffa kaffun-nahâri dzuyûlal-ghayâhib, faya‘ûdûna wa qad fâzû bil-maṭlûb, wa adrakû ridlal-maḥbûb, wa lam ya‘ud aḥadun minal-qaumi wa huwa khâ'ib", "id": "Mereka terus beristighfar hingga telapak siang menyingkap ujung kegelapan malam. Lalu mereka kembali dalam keadaan telah meraih apa yang dicari dan mendapatkan rida Sang Kekasih; tak seorang pun dari mereka kembali dengan tangan hampa.", "no": 8},
{"ar": "(لَا إِلٰهَ إِلَّا اللهُ) فَسُبْحَانَهُ وَتَعَالٰى مِنْ مَلِكٍ أَوْجَدَ نُوْرَ نَبِيِّهِ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ نُوْرِهِ قَبْلَ أَنْ يَخْلُقَ آدَمَ مِنَ الطِّيْنِ اللَّازِبِ، وَعَرَضَ فَخْرَهُ عَلَى الْأَشْيَاءِ وَقَالَ: هٰذَا سَيِّدُ الْأَنْبِيَاءِ، وَأَجَلُّ الْأَصْفِيَاءِ، وَأَكْرَمُ الْحَبَائِبِ", "lt": "(Lâ ilâha illallâh) fasubḥânahû wa ta‘âlâ min malikin aujada nûra nabiyyihî muḥammadin shallallâhu ‘alaihi wa sallama min nûrihî qabla an yakhluqa âdama minaṭ-ṭînil-lâzib, wa ‘aradla fakhrahû ‘alal-asyyâ'i wa qâla: hâdzâ sayyidul-anbiyâ', wa ajallul-ashfiyâ', wa akramul-ḥabâ'ib", "id": "(Tiada tuhan selain Allah) Maha Suci dan Mahatinggi Dia, Raja yang menciptakan cahaya Nabi-Nya, Muhammad ﷺ, dari cahaya-Nya sebelum menciptakan Adam dari tanah liat yang lekat. Dia memperlihatkan kemuliaannya kepada segala sesuatu dan berfirman: Inilah pemimpin para nabi, yang paling agung di antara orang-orang pilihan, dan yang paling mulia di antara para kekasih.", "no": 9},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 10},
{"ar": "قِيْلَ: هُوَ آدَمُ؟ قَالَ: آدَمُ بِهِ أُنِيْلُهُ أَعْلَى الْمَرَاتِبِ. قِيْلَ: هُوَ نُوْحٌ؟ قَالَ: نُوْحٌ بِهِ يَنْجُوْ مِنَ الْغَرَقِ وَيَهْلِكُ مَنْ خَالَفَهُ مِنَ الْأَهْلِ وَالْأَقَارِبِ", "lt": "Qîla: huwa âdam? qâla: âdamu bihî unîluhû a‘lal-marâtib. Qîla: huwa nûḥ? qâla: nûḥun bihî yanjû minal-gharaqi wa yahliku man khâlafahû minal-ahli wal-aqârib", "id": "Ditanyakan: Apakah dia Adam? Allah berfirman: Dengannya Aku berikan kepada Adam derajat tertinggi. Ditanyakan: Apakah dia Nuh? Allah berfirman: Dengannya Nuh selamat dari banjir, dan binasalah keluarga dan kerabat yang menentangnya.", "no": 11},
{"ar": "قِيْلَ: هُوَ إِبْرَاهِيْمُ؟ قَالَ: إِبْرَاهِيْمُ بِهِ تَقُوْمُ حُجَّتُهُ عَلَى عُبَّادِ الْأَصْنَامِ وَالْكَوَاكِبِ. قِيْلَ: هُوَ مُوْسٰى؟ قَالَ: مُوْسٰى أَخُوْهُ، وَلٰكِنْ هٰذَا حَبِيْبٌ وَمُوْسٰى كَلِيْمٌ وَمُخَاطَبٌ", "lt": "Qîla: huwa ibrâhîm? qâla: ibrâhîmu bihî taqûmu ḥujjatuhû ‘alâ ‘ubbâdil-ashnâmi wal-kawâkib. Qîla: huwa mûsâ? qâla: mûsâ akhûhu, wa lâkin hâdzâ ḥabîbun wa mûsâ kalîmun wa mukhâṭab", "id": "Ditanyakan: Apakah dia Ibrahim? Allah berfirman: Dengannya tegak hujah Ibrahim atas para penyembah berhala dan bintang. Ditanyakan: Apakah dia Musa? Allah berfirman: Musa adalah saudaranya; akan tetapi dia adalah kekasih, sedangkan Musa adalah yang diajak bicara.", "no": 12},
{"ar": "قِيْلَ: هُوَ عِيْسٰى؟ قَالَ: عِيْسٰى يُبَشِّرُ بِهِ، وَهُوَ بَيْنَ يَدَيْ نُبُوَّتِهِ كَالْحَاجِبِ", "lt": "Qîla: huwa ‘îsâ? qâla: ‘îsâ yubasysyiru bihî, wa huwa baina yadai nubuwwatihî kal-ḥâjib", "id": "Ditanyakan: Apakah dia Isa? Allah berfirman: Isa memberi kabar gembira tentang kedatangannya, dan Isa di hadapan kenabiannya bagaikan seorang pengawal.", "no": 13},
{"ar": "قِيْلَ: فَمَنْ هٰذَا الْحَبِيْبُ الْكَرِيْمُ الَّذِيْ أَلْبَسْتَهُ حُلَّةَ الْوَقَارِ، وَتَوَّجْتَهُ بِتِيْجَانِ الْمَهَابَةِ وَالْاِفْتِخَارِ، وَنَشَرْتَ عَلَى رَأْسِهِ الْعَصَائِبَ؟", "lt": "Qîla: faman hâdzal-ḥabîbul-karîmul-ladzî albastahû ḥullatal-waqâr, wa tawwajtahû bitîjânil-mahâbati wal-iftikhâr, wa nasyarta ‘alâ ra'sihil-‘ashâ'ib?", "id": "Ditanyakan: Siapakah kekasih mulia ini, yang Engkau kenakan kepadanya pakaian kewibawaan, Engkau mahkotai dengan mahkota keagungan dan kebanggaan, dan Engkau kibarkan di atas kepalanya panji-panji?", "no": 14},
{"ar": "قَالَ: هُوَ نَبِيٌّ اسْتَخَرْتُهُ مِنْ لُؤَيِّ بْنِ غَالِبٍ، يَمُوْتُ أَبُوْهُ وَأُمُّهُ وَيَكْفُلُهُ جَدُّهُ ثُمَّ عَمُّهُ الشَّقِيْقُ أَبُوْ طَالِبٍ", "lt": "Qâla: huwa nabiyyunis-takhartuhû min lu'ayyibni ghâlib, yamûtu abûhu wa ummuhû wa yakfuluhû jadduhû tsumma ‘ammuhusy-syaqîqu abû ṭâlib", "id": "Allah berfirman: Dia adalah nabi yang Aku pilih dari keturunan Lu'ay bin Ghalib. Ayah dan ibunya wafat, lalu ia diasuh oleh kakeknya, kemudian oleh pamannya, saudara kandung ayahnya, Abu Thalib.", "no": 15},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 16},
{"ar": "يُبْعَثُ مِنْ تِهَامَةَ بَيْنَ يَدَيِ الْقِيَامَةِ، فِيْ ظَهْرِهِ عَلَامَةٌ، تُظِلُّهُ الْغَمَامَةُ، تُطِيْعُهُ السَّحَائِبُ، فَجْرِيُّ الْجَبِيْنِ، لَيْلِيُّ الذَّوَائِبِ، أَلْفِيُّ الْأَنْفِ، مِيْمِيُّ الْفَمِ، نُوْنِيُّ الْحَاجِبِ", "lt": "Yub‘atsu min tihâmata baina yadayil-qiyâmah, fî dhahrihî ‘alâmah, tudhilluhul-ghamâmah, tuṭî‘uhus-saḥâ'ib, fajriyyul-jabîn, lailiyyudz-dzawâ'ib, alfiyyul-anfi, mîmiyyul-fami, nûniyyul-ḥâjib", "id": "Ia diutus dari Tihamah menjelang hari kiamat. Di punggungnya ada tanda (kenabian), awan menaunginya, mega-mega menaatinya. Dahinya bercahaya bagai fajar, rambutnya hitam bagai malam, hidungnya mancung bagai huruf alif, mulutnya indah bagai huruf mim, alisnya melengkung bagai huruf nun.", "no": 17},
{"ar": "سَمْعُهُ يَسْمَعُ صَرِيْرَ الْقَلَمِ، بَصَرُهُ إِلَى السَّبْعِ الطِّبَاقِ ثَاقِبٌ، قَدَمَاهُ قَبَّلَهُمَا الْبَعِيْرُ فَأَزَالَ مَا اشْتَكَاهُ مِنَ الْمِحَنِ وَالنَّوَائِبِ", "lt": "Sam‘uhû yasma‘u sharîral-qalam, basharuhû ilas-sab‘iṭ-ṭibâqi tsâqib, qadamâhu qabbalahumal-ba‘îru fa'azâla masy-takâhu minal-miḥani wan-nawâ'ib", "id": "Pendengarannya mendengar goresan pena (takdir), penglihatannya menembus tujuh lapis langit. Kedua telapak kakinya dicium seekor unta, maka hilanglah derita dan musibah yang dikeluhkan unta itu.", "no": 18},
{"ar": "آمَنَ بِهِ الضَّبُّ، وَسَلَّمَتْ عَلَيْهِ الْأَشْجَارُ، وَخَاطَبَتْهُ الْأَحْجَارُ، وَحَنَّ إِلَيْهِ الْجِذْعُ حَنِيْنَ حَزِيْنٍ نَادِبٍ", "lt": "Âmana bihidl-dlabb, wa sallamat ‘alaihil-asyjâr, wa khâṭabathul-aḥjâr, wa ḥanna ilaihil-jidz‘u ḥanîna ḥazînin nâdib", "id": "Biawak pun beriman kepadanya, pepohonan mengucapkan salam kepadanya, bebatuan berbicara dengannya, dan batang kurma merintih rindu kepadanya bagaikan rintihan orang yang berduka.", "no": 19},
{"ar": "يَدَاهُ تَظْهَرُ بَرَكَتُهُمَا فِي الْمَطَاعِمِ وَالْمَشَارِبِ، قَلْبُهُ لَا يَغْفُلُ وَلَا يَنَامُ وَلٰكِنْ لِلْخِدْمَةِ عَلَى الدَّوَامِ مُرَاقِبٌ، إِنْ أُوْذِيَ يَعْفُ وَلَا يُعَاقِبُ، وَإِنْ خُوْصِمَ يَصْمُتُ وَلَا يُجَاوِبُ", "lt": "Yadâhu tadh-haru barakatuhumâ fil-maṭâ‘imi wal-masyârib, qalbuhû lâ yaghfulu wa lâ yanâmu wa lâkin lil-khidmati ‘alad-dawâmi murâqib, in ûdziya ya‘fu wa lâ yu‘âqib, wa in khûshima yashmutu wa lâ yujâwib", "id": "Keberkahan kedua tangannya tampak pada makanan dan minuman. Hatinya tidak lalai dan tidak tidur, senantiasa terjaga untuk mengabdi. Bila disakiti ia memaafkan dan tidak membalas; bila dibantah ia diam dan tidak menjawab.", "no": 20},
{"ar": "أَرْفَعُهُ إِلَى أَشْرَفِ الْمَرَاتِبِ، فِيْ رَكْبَةٍ لَا تَنْبَغِيْ قَبْلَهُ وَلَا بَعْدَهُ لِرَاكِبٍ، فِيْ مَوْكِبٍ مِنَ الْمَلَائِكَةِ يَفُوْقُ عَلَى سَائِرِ الْمَوَاكِبِ، فَإِذَا ارْتَقَى عَلَى الْكَوْنَيْنِ، وَانْفَصَلَ عَنِ الْعَالَمَيْنِ، وَوَصَلَ إِلَى قَابِ قَوْسَيْنِ، كُنْتُ لَهُ أَنَا النَّدِيْمَ وَالْمُخَاطِبَ", "lt": "Arfa‘uhû ilâ asyrafil-marâtib, fî rakbatin lâ tanbaghî qablahû wa lâ ba‘dahû lirâkib, fî maukibin minal-malâ'ikati yafûqu ‘alâ sâ'iril-mawâkib, fa'idzar-taqâ ‘alal-kaunain, wanfashala ‘anil-‘âlamain, wa washala ilâ qâba qausain, kuntu lahû anan-nadîma wal-mukhâṭib", "id": "Aku angkat dia ke derajat yang paling mulia, dalam perjalanan yang tak pantas bagi seorang pun sebelum dan sesudahnya, dalam iring-iringan malaikat yang melebihi semua iring-iringan. Ketika ia telah naik melampaui dua alam, terpisah dari alam semesta, dan sampai pada jarak dua busur panah, Akulah yang menjadi teman bicaranya.", "no": 21},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 22},
{"ar": "ثُمَّ أَرُدُّهُ مِنَ الْعَرْشِ قَبْلَ أَنْ يَبْرُدَ الْفَرْشُ، وَقَدْ نَالَ جَمِيْعَ الْمَآرِبِ، فَإِذَا شُرِّفَتْ تُرْبَةُ طَيْبَةَ مِنْهُ بِأَشْرَفِ قَالِبٍ، سَعَتْ إِلَيْهِ أَرْوَاحُ الْمُحِبِّيْنَ عَلَى الْأَقْدَامِ وَالنَّجَائِبِ", "lt": "Tsumma aruddu-hû minal-‘arsyi qabla an yabrudal-farsy, wa qad nâla jamî‘al-ma'ârib, fa'idzâ syurrifat turbatu ṭaibata minhu bi'asyrafi qâlib, sa‘at ilaihi arwâḥul-muḥibbîna ‘alal-aqdâmi wan-najâ'ib", "id": "Kemudian Aku kembalikan dia dari Arasy sebelum tempat tidurnya menjadi dingin, dan ia telah meraih seluruh hajatnya. Ketika tanah Thaibah (Madinah) dimuliakan dengan jasadnya yang paling mulia, ruh-ruh para pecinta datang kepadanya dengan berjalan kaki dan berkendaraan.", "no": 23},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 24}]},
{judul:"Shalatullah Ma Lahat Kawakib",isi:[
{"ar": "صَلَاةُ اللهِ مَا لَاحَتْ كَوَاكِبْ ۞ عَلَى أَحْمَدْ خَيْرِ مَنْ رَكِبَ النَّجَائِبْ", "lt": "Shalâtullâhi mâ lâḥat kawâkib ۞ ‘alâ aḥmad khairi man rakiban-najâ'ib", "id": "Shalawat Allah (tercurah) selama bintang-bintang bersinar, kepada Ahmad, sebaik-baik orang yang menunggang unta.", "no": 1},
{"ar": "حَدَى حَادِي السُّرَى بِاسْمِ الْحَبَائِبْ ۞ فَهَزَّ السُّكْرُ أَعْطَافَ الرَّكَائِبْ", "lt": "Ḥadâ ḥâdis-surâ bismil-ḥabâ'ib ۞ fahazzas-sukru a‘ṭâfar-rakâ'ib", "id": "Penggiring unta di malam hari bersenandung menyebut nama para kekasih, maka mabuk rindu menggoyang leher-leher unta tunggangan.", "no": 2},
{"ar": "أَلَمْ تَرَهَا وَقَدْ مَدَّتْ خُطَاهَا ۞ وَسَالَتْ مِنْ مَدَامِعِهَا سَحَائِبْ", "lt": "Alam tarahâ wa qad maddat khuṭâhâ ۞ wa sâlat min madâmi‘ihâ saḥâ'ib", "id": "Tidakkah engkau lihat unta-unta itu memanjangkan langkahnya, dan dari matanya mengalir air mata bagai hujan?", "no": 3},
{"ar": "وَمَالَتْ لِلْحِمٰى طَرَبًا وَحَنَّتْ ۞ إِلَى تِلْكَ الْمَعَالِمِ وَالْمَلَاعِبْ", "lt": "Wa mâlat lil-ḥimâ ṭaraban wa ḥannat ۞ ilâ tilkal-ma‘âlimi wal-malâ‘ib", "id": "Ia condong ke tanah haram dengan gembira dan rindu kepada tempat-tempat bersejarah dan tempat bermain itu.", "no": 4},
{"ar": "فَدَعْ جَذْبَ الزِّمَامِ وَلَا تَسُقْهَا ۞ فَقَائِدُ شَوْقِهَا لِلْحَيِّ جَاذِبْ", "lt": "Fada‘ jadzbaz-zimâmi wa lâ tasuqhâ ۞ faqâ'idu syauqihâ lil-ḥayyi jâdzib", "id": "Biarkan tali kekangnya, jangan engkau giring; penuntun kerinduannya telah menariknya menuju kampung (sang kekasih).", "no": 5},
{"ar": "فَهِمْ طَرَبًا كَمَا هَامَتْ وَإِلَّا ۞ فَإِنَّكَ فِيْ طَرِيْقِ الْحُبِّ كَاذِبْ", "lt": "Fahim ṭaraban kamâ hâmat wa illâ ۞ fa innaka fî ṭarîqil-ḥubbi kâdzib", "id": "Maka larutlah dalam rindu sebagaimana unta itu larut; jika tidak, sungguh engkau berdusta di jalan cinta.", "no": 6},
{"ar": "أَمَا هٰذَا الْعَقِيْقُ بَدَا وَهٰذِيْ ۞ قِبَابُ الْحَيِّ لَاحَتْ وَالْمَضَارِبْ", "lt": "Amâ hâdzal-‘aqîqu badâ wa hâdzî ۞ qibâbul-ḥayyi lâḥat wal-madlârib", "id": "Tidakkah engkau lihat lembah Aqiq telah tampak, dan kubah-kubah kampung serta kemah-kemahnya telah terlihat?", "no": 7},
{"ar": "وَتِلْكَ الْقُبَّةُ الْخَضْرَاءُ فِيْهَا ۞ نَبِيٌّ نُوْرُهُ يَجْلُو الْغَيَاهِبْ", "lt": "Wa tilkal-qubbatul-khadlrâ'u fîhâ ۞ nabiyyun nûruhû yajlul-ghayâhib", "id": "Dan itulah kubah hijau, di dalamnya ada Nabi yang cahayanya menyingkap kegelapan.", "no": 8},
{"ar": "وَقَدْ صَحَّ الرِّضَا وَدَنَا التَّلَاقِيْ ۞ وَقَدْ جَاءَ الْهَنَا مِنْ كُلِّ جَانِبْ", "lt": "Wa qad shaḥḥar-ridlâ wa danat-talâqî ۞ wa qad jâ'al-hanâ min kulli jânib", "id": "Rida telah nyata, pertemuan telah dekat, dan kebahagiaan datang dari segala penjuru.", "no": 9},
{"ar": "فَقُلْ لِلنَّفْسِ دُوْنَكِ وَالتَّمَلِّيْ ۞ فَمَا دُوْنَ الْحَبِيْبِ الْيَوْمَ حَاجِبْ", "lt": "Faqul lin-nafsi dûnaki wat-tamallî ۞ famâ dûnal-ḥabîbil-yauma ḥâjib", "id": "Katakan kepada diri: Inilah dia, puaskanlah dirimu memandang, karena hari ini tak ada lagi penghalang antara engkau dan Sang Kekasih.", "no": 10},
{"ar": "تَمَلَّيْ بِالْحَبِيْبِ بِكُلِّ قَصْدٍ ۞ فَقَدْ حَصَلَ الْهَنَا وَالضِّدُّ غَائِبْ", "lt": "Tamallai bil-ḥabîbi bikulli qashdin ۞ faqad ḥashalal-hanâ wadl-dliddu ghâ'ib", "id": "Puaskanlah dirimu dengan Sang Kekasih dengan segenap tujuan, sebab kebahagiaan telah tercapai dan segala yang berlawanan telah sirna.", "no": 11},
{"ar": "نَبِيُّ اللهِ خَيْرُ الْخَلْقِ جَمْعًا ۞ لَهُ أَعْلَى الْمَنَاصِبِ وَالْمَرَاتِبْ", "lt": "Nabiyyullâhi khairul-khalqi jam‘an ۞ lahû a‘lal-manâshibi wal-marâtib", "id": "Nabi Allah, sebaik-baik seluruh makhluk; baginya kedudukan dan derajat yang tertinggi.", "no": 12},
{"ar": "لَهُ الْجَاهُ الرَّفِيْعُ لَهُ الْمَعَالِيْ ۞ لَهُ الشَّرَفُ الْمُؤَبَّدُ وَالْمَنَاقِبْ", "lt": "Lahul-jâhur-rafî‘u lahul-ma‘âlî ۞ lahusy-syaraful-mu'abbadu wal-manâqib", "id": "Baginya kedudukan yang luhur, baginya segala keagungan, baginya kemuliaan yang abadi dan segala keutamaan.", "no": 13},
{"ar": "فَلَوْ أَنَّا سَعَيْنَا كُلَّ يَوْمٍ ۞ عَلَى الْأَحْدَاقِ لَا فَوْقَ النَّجَائِبْ", "lt": "Falau annâ sa‘ainâ kulla yaumin ۞ ‘alal-aḥdâqi lâ fauqan-najâ'ib", "id": "Seandainya setiap hari kami berjalan (menuju beliau) di atas bola mata, bukan di atas unta tunggangan,", "no": 14},
{"ar": "وَلَوْ أَنَّا عَمِلْنَا كُلَّ حِيْنٍ ۞ لِأَحْمَدَ مَوْلِدًا قَدْ كَانَ وَاجِبْ", "lt": "Wa lau annâ ‘amilnâ kulla ḥînin ۞ li'aḥmada maulidan qad kâna wâjib", "id": "dan seandainya setiap saat kami mengadakan maulid untuk Ahmad, sungguh itu sudah sepantasnya.", "no": 15},
{"ar": "عَلَيْهِ مِنَ الْمُهَيْمِنِ كُلَّ وَقْتٍ ۞ صَلَاةٌ مَا بَدَا نُوْرُ الْكَوَاكِبْ", "lt": "‘Alaihi minal-muhaimini kulla waqtin ۞ shalâtun mâ badâ nûrul-kawâkib", "id": "Semoga tercurah kepadanya dari (Allah) Yang Maha Memelihara setiap saat shalawat, selama cahaya bintang-bintang tampak,", "no": 16},
{"ar": "تَعُمُّ الْآلَ وَالْأَصْحَابَ طُرًّا ۞ جَمِيْعَهُمُ وَعِتْرَتَهُ الْأَطَايِبْ", "lt": "Ta‘ummul-âla wal-ash-ḥâba ṭurran ۞ jamî‘ahumû wa ‘itratahul-aṭâyib", "id": "meliputi keluarga dan sahabat seluruhnya, serta keturunannya yang baik-baik.", "no": 17},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 18}]},
{judul:"Fa Subhana Man Khashshahu",isi:[
{"ar": "فَسُبْحَانَ مَنْ خَصَّهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِأَشْرَفِ الْمَنَاصِبِ وَالْمَرَاتِبِ، أَحْمَدُهُ عَلَى مَا مَنَحَ مِنَ الْمَوَاهِبِ", "lt": "Fasubḥâna man khash-shahû shallallâhu ‘alaihi wa sallama bi'asyrafil-manâshibi wal-marâtib, aḥmaduhû ‘alâ mâ manaḥa minal-mawâhib", "id": "Maha Suci (Allah) yang telah mengistimewakan beliau ﷺ dengan kedudukan dan derajat yang paling mulia. Aku memuji-Nya atas segala anugerah yang telah Dia berikan.", "no": 1},
{"ar": "وَأَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيْكَ لَهُ رَبُّ الْمَشَارِقِ وَالْمَغَارِبِ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُوْلُهُ الْمَبْعُوْثُ إِلَى سَائِرِ الْأَعَاجِمِ وَالْأَعَارِبِ", "lt": "Wa asyhadu an lâ ilâha illallâhu waḥdahû lâ syarîka lahû rabbul-masyâriqi wal-maghârib, wa asyhadu anna muḥammadan ‘abduhû wa rasûluhul-mab‘ûtsu ilâ sâ'iril-a‘âjimi wal-a‘ârib", "id": "Aku bersaksi bahwa tiada tuhan selain Allah, Yang Maha Esa, tiada sekutu bagi-Nya, Tuhan segala timur dan barat; dan aku bersaksi bahwa Muhammad adalah hamba dan utusan-Nya, yang diutus kepada seluruh bangsa Ajam dan Arab.", "no": 2},
{"ar": "صَلَّى اللهُ عَلَيْهِ وَعَلَى آلِهِ وَأَصْحَابِهِ أُوْلِي الْمَآثِرِ وَالْمَنَاقِبِ، صَلَاةً وَسَلَامًا دَائِمَيْنِ مُتَلَازِمَيْنِ يَأْتِيْ قَائِلُهُمَا يَوْمَ الْقِيَامَةِ غَيْرَ خَائِبٍ", "lt": "Shallallâhu ‘alaihi wa ‘alâ âlihî wa ash-ḥâbihî ulil-ma'âtsiri wal-manâqib, shalâtan wa salâman dâ'imaini mutalâzimaini ya'tî qâ'iluhumâ yaumal-qiyâmati ghaira khâ'ib", "id": "Semoga Allah melimpahkan shalawat kepadanya, keluarganya, dan para sahabatnya yang memiliki jasa dan keutamaan; shalawat dan salam yang terus-menerus dan tak terpisahkan, yang pengucapnya akan datang pada hari kiamat tanpa kecewa.", "no": 3},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 4}]},
{judul:"Hadis Pertama: Awwalu Ma Nastaftihu",isi:[
{"ar": "بِسْمِ اللهِ الرَّحْمٰنِ الرَّحِيْمِ، أَوَّلُ مَا نَسْتَفْتِحُ بِإِيْرَادِ حَدِيْثَيْنِ وَرَدَا عَنْ نَبِيٍّ كَانَ قَدْرُهُ عَظِيْمًا، وَنَسَبُهُ كَرِيْمًا، وَصِرَاطُهُ مُسْتَقِيْمًا", "lt": "Bismillâhir-raḥmânir-raḥîm, awwalu mâ nastaftiḥu bi'îrâdi ḥadîtsaini waradâ ‘an nabiyyin kâna qadruhû ‘adhîmâ, wa nasabuhû karîmâ, wa shirâṭuhû mustaqîmâ", "id": "Dengan nama Allah Yang Maha Pengasih lagi Maha Penyayang. Yang pertama kami buka (bacaan ini) dengan menyebutkan dua hadis yang diriwayatkan dari seorang nabi yang agung derajatnya, mulia nasabnya, dan lurus jalannya.", "no": 1},
{"ar": "قَالَ فِيْ حَقِّهِ مَنْ لَمْ يَزَلْ سَمِيْعًا عَلِيْمًا: إِنَّ اللهَ وَمَلَائِكَتَهُ يُصَلُّوْنَ عَلَى النَّبِيِّ يَا أَيُّهَا الَّذِيْنَ آمَنُوْا صَلُّوْا عَلَيْهِ وَسَلِّمُوْا تَسْلِيْمًا", "lt": "Qâla fî ḥaqqihî man lam yazal samî‘an ‘alîmâ: innallâha wa malâ'ikatahû yushallûna ‘alan-nabiyy, yâ ayyuhal-ladzîna âmanû shallû ‘alaihi wa sallimû taslîmâ", "id": "Tentang beliau, (Allah) Yang senantiasa Maha Mendengar lagi Maha Mengetahui berfirman: Sesungguhnya Allah dan para malaikat-Nya bershalawat untuk Nabi. Wahai orang-orang yang beriman, bershalawatlah kamu untuknya dan ucapkanlah salam dengan penuh penghormatan.", "no": 2},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 3},
{"ar": "(اَلْحَدِيْثُ الْأَوَّلُ) عَنْ بَحْرِ الْعِلْمِ الدَّافِقِ، وَلِسَانِ الْقُرْآنِ النَّاطِقِ، أَوْحَدِ عُلَمَاءِ النَّاسِ، سَيِّدِنَا عَبْدِ اللهِ بْنِ سَيِّدِنَا الْعَبَّاسِ رَضِيَ اللهُ عَنْهُمَا، عَنْ رَسُوْلِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: إِنَّ قُرَيْشًا كَانَتْ نُوْرًا بَيْنَ يَدَيِ اللهِ عَزَّ وَجَلَّ قَبْلَ أَنْ يَخْلُقَ آدَمَ بِأَلْفَيْ عَامٍ، يُسَبِّحُ اللهَ ذٰلِكَ النُّوْرُ وَتُسَبِّحُ الْمَلَائِكَةُ بِتَسْبِيْحِهِ", "lt": "(Al-ḥadîtsul-awwal) ‘an baḥril-‘ilmid-dâfiq, wa lisânil-qur'ânin-nâṭiq, auḥadi ‘ulamâ'in-nâs, sayyidinâ ‘abdillâhibni sayyidinal-‘abbâsi radliyallâhu ‘anhumâ, ‘an rasûlillâhi shallallâhu ‘alaihi wa sallama annahû qâla: inna quraisyan kânat nûran baina yadayillâhi ‘azza wa jalla qabla an yakhluqa âdama bi'alfai ‘âm, yusabbiḥullâha dzâlikan-nûru wa tusabbiḥul-malâ'ikatu bitasbîḥih", "id": "(Hadis pertama) Dari lautan ilmu yang melimpah, juru bicara Al-Qur'an, orang yang paling alim di antara manusia, Sayyidina Abdullah putra Sayyidina Abbas radhiyallahu ‘anhuma, dari Rasulullah ﷺ, beliau bersabda: Sesungguhnya Quraisy (yakni nur Nabi) dahulu berupa cahaya di hadapan Allah ‘Azza wa Jalla dua ribu tahun sebelum Dia menciptakan Adam. Cahaya itu bertasbih kepada Allah, dan para malaikat pun bertasbih mengikuti tasbihnya.", "no": 4},
{"ar": "فَلَمَّا خَلَقَ اللهُ آدَمَ أَوْدَعَ ذٰلِكَ النُّوْرَ فِيْ طِيْنَتِهِ، قَالَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: فَأَهْبَطَنِيَ اللهُ عَزَّ وَجَلَّ إِلَى الْأَرْضِ فِيْ ظَهْرِ آدَمَ، وَحَمَلَنِيْ فِي السَّفِيْنَةِ فِيْ صُلْبِ نُوْحٍ، وَجَعَلَنِيْ فِيْ صُلْبِ الْخَلِيْلِ إِبْرَاهِيْمَ حِيْنَ قُذِفَ بِهِ فِي النَّارِ", "lt": "Falammâ khalaqallâhu âdama auda‘a dzâlikan-nûra fî ṭînatih, qâla shallallâhu ‘alaihi wa sallam: fa ahbaṭaniyallâhu ‘azza wa jalla ilal-ardli fî dhahri âdam, wa ḥamalanî fis-safînati fî shulbi nûḥ, wa ja‘alanî fî shulbil-khalîli ibrâhîma ḥîna qudzifa bihî fin-nâr", "id": "Ketika Allah menciptakan Adam, Dia menitipkan cahaya itu dalam tanah asal kejadiannya. Rasulullah ﷺ bersabda: Lalu Allah ‘Azza wa Jalla menurunkanku ke bumi di dalam punggung Adam, membawaku di dalam bahtera di sulbi Nuh, dan menjadikanku di sulbi Al-Khalil Ibrahim ketika ia dilemparkan ke dalam api.", "no": 5},
{"ar": "وَلَمْ يَزَلِ اللهُ عَزَّ وَجَلَّ يُنَقِّلُنِيْ مِنَ الْأَصْلَابِ الطَّاهِرَةِ إِلَى الْأَرْحَامِ الزَّكِيَّةِ الْفَاخِرَةِ، حَتّٰى أَخْرَجَنِيَ اللهُ مِنْ بَيْنِ أَبَوَيَّ وَهُمَا لَمْ يَلْتَقِيَا عَلَى سِفَاحٍ قَطُّ", "lt": "Wa lam yazalillâhu ‘azza wa jalla yunaqqilunî minal-ashlâbiṭ-ṭâhirati ilal-arḥâmiz-zakiyyatil-fâkhirah, ḥattâ akhrajaniyallâhu min baini abawayya wa humâ lam yaltaqiyâ ‘alâ sifâḥin qaṭṭ", "id": "Allah ‘Azza wa Jalla senantiasa memindahkanku dari sulbi-sulbi yang suci ke rahim-rahim yang bersih lagi mulia, hingga Allah melahirkanku dari kedua orang tuaku, dan keduanya sama sekali tidak pernah bertemu dalam perzinaan.", "no": 6},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 7}]},
{judul:"Hadis Kedua: Ka'bul Ahbar",isi:[
{"ar": "(اَلْحَدِيْثُ الثَّانِيْ) عَنْ عَطَاءِ بْنِ يَسَارٍ، عَنْ كَعْبِ الْأَحْبَارِ، قَالَ: عَلَّمَنِيْ أَبِي التَّوْرَاةَ إِلَّا سِفْرًا وَاحِدًا كَانَ يَخْتِمُهُ وَيُدْخِلُهُ الصُّنْدُوْقَ، فَلَمَّا مَاتَ أَبِيْ فَتَحْتُهُ فَإِذَا فِيْهِ:", "lt": "(Al-ḥadîtsuts-tsânî) ‘an ‘aṭâ'ibni yasâr, ‘an ka‘bil-aḥbâr, qâla: ‘allamanî abit-taurâta illâ sifran wâḥidan kâna yakhtimuhû wa yudkhiluhush-shundûq, falammâ mâta abî fataḥtuhû fa'idzâ fîh:", "id": "(Hadis kedua) Dari Atha' bin Yasar, dari Ka‘ab Al-Ahbar, ia berkata: Ayahku mengajariku Taurat kecuali satu lembaran yang ia segel dan simpan di dalam peti. Ketika ayahku wafat, aku membukanya, ternyata di dalamnya tertulis:", "no": 1},
{"ar": "نَبِيٌّ يَخْرُجُ آخِرَ الزَّمَانِ، مَوْلِدُهُ بِمَكَّةَ، وَهِجْرَتُهُ بِالْمَدِيْنَةِ، وَسُلْطَانُهُ بِالشَّامِ، يَقُصُّ شَعْرَهُ، وَيَتَّزِرُ عَلَى وَسَطِهِ، يَكُوْنُ خَيْرَ الْأَنْبِيَاءِ، وَأُمَّتُهُ خَيْرَ الْأُمَمِ", "lt": "Nabiyyun yakhruju âkhiraz-zamân, mauliduhû bimakkah, wa hijratuhû bil-madînah, wa sulṭânuhû bisy-syâm, yaqushshu sya‘rahû, wa yattaziru ‘alâ wasaṭih, yakûnu khairal-anbiyâ', wa ummatuhû khairal-umam", "id": "Seorang nabi akan muncul di akhir zaman, kelahirannya di Makkah, hijrahnya ke Madinah, dan kekuasaannya sampai ke Syam. Ia memotong rambutnya dan memakai sarung sampai pertengahan betisnya. Ia adalah sebaik-baik nabi, dan umatnya sebaik-baik umat.", "no": 2},
{"ar": "يُكَبِّرُوْنَ اللهَ تَعَالٰى عَلَى كُلِّ شَرَفٍ، يَصُفُّوْنَ فِي الصَّلَاةِ كَصُفُوْفِهِمْ فِي الْقِتَالِ، قُلُوْبُهُمْ مَصَاحِفُهُمْ، يَحْمَدُوْنَ اللهَ تَعَالٰى عَلَى كُلِّ شِدَّةٍ وَرَخَاءٍ", "lt": "Yukabbirûnallâha ta‘âlâ ‘alâ kulli syaraf, yashuffûna fish-shalâti kashufûfihim fil-qitâl, qulûbuhum mashâḥifuhum, yaḥmadûnallâha ta‘âlâ ‘alâ kulli syiddatin wa rakhâ'", "id": "Mereka bertakbir kepada Allah Ta‘ala di setiap tempat yang tinggi, bershaf dalam salat seperti barisan mereka dalam peperangan, hati mereka adalah mushaf-mushaf mereka, dan mereka memuji Allah Ta‘ala dalam setiap kesempitan dan kelapangan.", "no": 3},
{"ar": "ثُلُثٌ يَدْخُلُوْنَ الْجَنَّةَ بِغَيْرِ حِسَابٍ، وَثُلُثٌ يَأْتُوْنَ بِذُنُوْبِهِمْ وَخَطَايَاهُمْ فَيُغْفَرُ لَهُمْ، وَثُلُثٌ يَأْتُوْنَ بِذُنُوْبٍ وَخَطَايَا عِظَامٍ", "lt": "Tsulutsun yadkhulûnal-jannata bighairi ḥisâb, wa tsulutsun ya'tûna bidzunûbihim wa khaṭâyâhum fayughfaru lahum, wa tsulutsun ya'tûna bidzunûbin wa khaṭâyâ ‘idhâm", "id": "Sepertiga dari mereka masuk surga tanpa hisab, sepertiga datang dengan dosa dan kesalahan mereka lalu diampuni, dan sepertiga lagi datang dengan dosa dan kesalahan yang besar.", "no": 4},
{"ar": "فَيَقُوْلُ اللهُ تَعَالٰى لِلْمَلَائِكَةِ: اذْهَبُوْا فَزِنُوْهُمْ، فَيَقُوْلُوْنَ: يَا رَبَّنَا وَجَدْنَاهُمْ أَسْرَفُوْا عَلَى أَنْفُسِهِمْ، وَوَجَدْنَا أَعْمَالَهُمْ مِنَ الذُّنُوْبِ كَأَمْثَالِ الْجِبَالِ، غَيْرَ أَنَّهُمْ يَشْهَدُوْنَ أَنْ لَا إِلٰهَ إِلَّا اللهُ وَأَنَّ مُحَمَّدًا رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ", "lt": "Fayaqûlullâhu ta‘âlâ lil-malâ'ikah: idzhabû fazinûhum, fayaqûlûna: yâ rabbanâ wajadnâhum asrafû ‘alâ anfusihim, wa wajadnâ a‘mâlahum minadz-dzunûbi ka'amtsâlil-jibâl, ghaira annahum yasyhadûna an lâ ilâha illallâhu wa anna muḥammadan rasûlullâhi shallallâhu ‘alaihi wa sallam", "id": "Maka Allah Ta‘ala berfirman kepada para malaikat: Pergilah dan timbanglah (amal) mereka. Para malaikat berkata: Wahai Tuhan kami, kami dapati mereka melampaui batas atas diri mereka sendiri, dan kami dapati amal mereka penuh dosa laksana gunung-gunung; hanya saja mereka bersaksi bahwa tiada tuhan selain Allah dan bahwa Muhammad adalah utusan Allah ﷺ.", "no": 5},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 6},
{"ar": "فَيَقُوْلُ الْحَقُّ: وَعِزَّتِيْ وَجَلَالِيْ، لَا جَعَلْتُ مَنْ أَخْلَصَ لِيْ بِالشَّهَادَةِ كَمَنْ كَذَّبَ بِيْ، أَدْخِلُوْهُمُ الْجَنَّةَ بِرَحْمَتِيْ", "lt": "Fayaqûlul-ḥaqq: wa ‘izzatî wa jalâlî, lâ ja‘altu man akhlasha lî bisy-syahâdati kaman kadzdzaba bî, adkhilûhumul-jannata biraḥmatî", "id": "Maka Allah Yang Mahabenar berfirman: Demi keperkasaan dan keagungan-Ku, tidak akan Aku samakan orang yang tulus bersaksi kepada-Ku dengan orang yang mendustakan-Ku. Masukkanlah mereka ke dalam surga dengan rahmat-Ku.", "no": 7},
{"ar": "يَا أَعَزَّ جَوَاهِرِ الْعُقُوْدِ، وَخُلَاصَةَ إِكْسِيْرِ سِرِّ الْوُجُوْدِ، مَادِحُكَ قَاصِرٌ وَلَوْ جَاءَ بِبَذْلِ الْمَجْهُوْدِ، وَوَاصِفُكَ عَاجِزٌ عَنْ حَصْرِ مَا حَوَيْتَ مِنْ خِصَالِ الْكَرَمِ وَالْجُوْدِ", "lt": "Yâ a‘azza jawâhiril-‘uqûd, wa khulâshata iksîri sirril-wujûd, mâdiḥuka qâshirun wa lau jâ'a bibadzlil-majhûd, wa wâshifuka ‘âjizun ‘an ḥashri mâ ḥawaita min khishâlil-karami wal-jûd", "id": "Wahai permata paling berharga dalam untaian kalung, wahai sari pati rahasia keberadaan; orang yang memujimu tetap kurang meski telah mengerahkan segenap upaya, dan orang yang menyifatimu tak mampu menghitung sifat-sifat kemuliaan dan kedermawanan yang engkau miliki.", "no": 8},
{"ar": "اَلْكَوْنُ إِشَارَةٌ وَأَنْتَ الْمَقْصُوْدُ، يَا أَشْرَفَ مَنْ نَالَ الْمَقَامَ الْمَحْمُوْدَ، وَجَاءَتْ رُسُلٌ مِنْ قَبْلِكَ لٰكِنَّهُمْ بِالرِّفْعَةِ وَالْعُلَا لَكَ شُهُوْدٌ", "lt": "Al-kaunu isyâratun wa antal-maqshûd, yâ asyrafa man nâlal-maqâmal-maḥmûd, wa jâ'at rusulun min qablika lâkinnahum bir-rif‘ati wal-‘ulâ laka syuhûd", "id": "Alam semesta hanyalah isyarat, dan engkaulah yang dimaksud. Wahai yang paling mulia yang meraih Maqam Mahmud; para rasul telah datang sebelummu, namun mereka semua menjadi saksi atas ketinggian dan keluhuranmu.", "no": 9},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 10}]},
{judul:"Ahdliru Qulubakum",isi:[
{"ar": "أَحْضِرُوْا قُلُوْبَكُمْ يَا مَعْشَرَ ذَوِي الْأَلْبَابِ، حَتّٰى أَجْلُوَ لَكُمْ عَرَائِسَ مَعَانِيْ أَجَلِّ الْأَحْبَابِ، الْمَخْصُوْصِ بِأَشْرَفِ الْأَلْقَابِ، الرَّاقِيْ إِلَى حَضْرَةِ الْمَلِكِ الْوَهَّابِ، حَتّٰى نَظَرَ إِلَى جَمَالِهِ بِلَا سِتْرٍ وَلَا حِجَابٍ", "lt": "Aḥdlirû qulûbakum yâ ma‘syara dzawil-albâb, ḥattâ ajluwa lakum ‘arâ'isa ma‘ânî ajallil-aḥbâb, al-makhshûshi bi'asyrafil-alqâb, ar-râqî ilâ ḥadlratil-malikil-wahhâb, ḥattâ nadhara ilâ jamâlihî bilâ sitrin wa lâ ḥijâb", "id": "Hadirkanlah hati kalian, wahai orang-orang yang berakal, agar aku tampakkan kepada kalian keindahan makna-makna (sifat) kekasih yang paling agung, yang diistimewakan dengan gelar-gelar paling mulia, yang naik ke hadirat Raja Yang Maha Pemberi, hingga ia memandang keindahan-Nya tanpa tirai dan tanpa hijab.", "no": 1},
{"ar": "فَلَمَّا آنَ أَوَانُ ظُهُوْرِ شَمْسِ الرِّسَالَةِ فِيْ سَمَاءِ الْجَلَالَةِ، خَرَجَ بِهِ مَرْسُوْمُ الْجَلِيْلِ، لِنَقِيْبِ الْمَمْلَكَةِ جِبْرِيْلَ: يَا جِبْرِيْلُ نَادِ فِيْ سَائِرِ الْمَخْلُوْقَاتِ، مِنْ أَهْلِ الْأَرْضِ وَالسَّمٰوَاتِ، بِالتَّهَانِيْ وَالْبِشَارَاتِ", "lt": "Falammâ âna awânu dhuhûri syamsir-risâlati fî samâ'il-jalâlah, kharaja bihî marsûmul-jalîl, linaqîbil-mamlakati jibrîl: yâ jibrîlu nâdi fî sâ'iril-makhlûqât, min ahlil-ardli was-samâwât, bit-tahânî wal-bisyârât", "id": "Ketika telah tiba saatnya terbit matahari risalah di langit keagungan, keluarlah titah Yang Mahaagung kepada pemimpin kerajaan (langit), Jibril: Wahai Jibril, serukanlah kepada seluruh makhluk, penghuni bumi dan langit, ucapan selamat dan kabar gembira.", "no": 2},
{"ar": "فَإِنَّ النُّوْرَ الْمَصُوْنَ، وَالسِّرَّ الْمَكْنُوْنَ، الَّذِيْ أَوْجَدْتُهُ قَبْلَ وُجُوْدِ الْأَشْيَاءِ، وَإِبْدَاعِ الْأَرْضِ وَالسَّمَاءِ، أَنْقُلُهُ فِيْ هٰذِهِ اللَّيْلَةِ إِلَى بَطْنِ أُمِّهِ مَسْرُوْرًا، أَمْلَأُ بِهِ الْكَوْنَ نُوْرًا، وَأَكْفُلُهُ يَتِيْمًا، وَأُطَهِّرُهُ وَأَهْلَ بَيْتِهِ تَطْهِيْرًا", "lt": "Fa'innan-nûral-mashûn, was-sirral-maknûn, al-ladzî aujadtuhû qabla wujûdil-asyyâ', wa ibdâ‘il-ardli was-samâ', anquluhû fî hâdzihil-lailati ilâ baṭni ummihî masrûrâ, amla'u bihil-kauna nûrâ, wa akfuluhû yatîmâ, wa uṭahhiruhû wa ahla baitihî taṭhîrâ", "id": "Sesungguhnya cahaya yang terpelihara dan rahasia yang tersimpan, yang telah Aku ciptakan sebelum adanya segala sesuatu dan sebelum penciptaan bumi dan langit, akan Aku pindahkan pada malam ini ke dalam kandungan ibunya dengan penuh kegembiraan. Dengannya Aku penuhi alam semesta dengan cahaya. Aku akan memeliharanya sebagai anak yatim, dan Aku sucikan dia beserta ahli baitnya dengan sesuci-sucinya.", "no": 3},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 4},
{"ar": "فَاهْتَزَّ الْعَرْشُ طَرَبًا وَاسْتِبْشَارًا، وَازْدَادَ الْكُرْسِيُّ هَيْبَةً وَوَقَارًا، وَامْتَلَأَتِ السَّمٰوَاتُ أَنْوَارًا، وَضَجَّتِ الْمَلَائِكَةُ تَهْلِيْلًا وَتَمْجِيْدًا وَاسْتِغْفَارًا", "lt": "Fahtazzal-‘arsyu ṭaraban was-tibsyârâ, wazdâdal-kursiyyu haibatan wa waqârâ, wamtala'atis-samâwâtu anwârâ, wa dlajjatil-malâ'ikatu tahlîlan wa tamjîdan was-tighfârâ", "id": "Maka Arasy bergetar karena gembira dan suka cita, Kursi bertambah wibawa dan keagungannya, langit-langit dipenuhi cahaya, dan para malaikat bergemuruh mengucapkan tahlil, pujian keagungan, dan istighfar.", "no": 5},
{"ar": "سُبْحَانَ اللهِ وَالْحَمْدُ لِلّٰهِ وَلَا إِلٰهَ إِلَّا اللهُ وَاللهُ أَكْبَرُ (٣×)", "lt": "Subḥânallâhi wal-ḥamdu lillâhi wa lâ ilâha illallâhu wallâhu akbar (3×)", "id": "Maha Suci Allah, segala puji bagi Allah, tiada tuhan selain Allah, dan Allah Mahabesar. (dibaca 3 kali)", "no": 6},
{"ar": "وَلَمْ تَزَلْ أُمُّهُ تَرٰى أَنْوَاعًا مِنْ فَخْرِهِ وَفَضْلِهِ، إِلَى نِهَايَةِ تَمَامِ حَمْلِهِ، فَلَمَّا اشْتَدَّ بِهَا الطَّلْقُ، بِإِذْنِ رَبِّ الْخَلْقِ، وَضَعَتِ الْحَبِيْبَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَاجِدًا شَاكِرًا حَامِدًا كَأَنَّهُ الْبَدْرُ فِيْ تَمَامِهِ", "lt": "Wa lam tazal ummuhû tarâ anwâ‘an min fakhrihî wa fadllih, ilâ nihâyati tamâmi ḥamlih, falammasy-tadda bihaṭ-ṭalqu, bi'idzni rabbil-khalqi, wadla‘atil-ḥabîba shallallâhu ‘alaihi wa sallama sâjidan syâkiran ḥâmidan ka'annahul-badru fî tamâmih", "id": "Ibunya senantiasa menyaksikan berbagai kemuliaan dan keutamaannya hingga sempurna masa kandungannya. Ketika rasa sakit melahirkan semakin kuat, dengan izin Tuhan semesta makhluk, ia melahirkan sang kekasih ﷺ dalam keadaan bersujud, bersyukur, dan memuji, laksana bulan purnama yang sempurna.", "no": 7}]},
{judul:"Mahallul Qiyam",isi:[
{"ar": "صَلَّى اللهُ عَلَى مُحَمَّدْ ۞ صَلَّى اللهُ عَلَيْهِ وَسَلَّمْ", "lt": "Shallallâhu ‘alâ muḥammad ۞ shallallâhu ‘alaihi wa sallam", "id": "Semoga Allah melimpahkan rahmat kepada Nabi Muhammad; semoga Allah melimpahkan rahmat dan salam kepadanya.", "no": 1},
{"ar": "يَا نَبِيْ سَلَامْ عَلَيْكَ ۞ يَا رَسُوْلْ سَلَامْ عَلَيْكَ", "lt": "Yâ nabî salâm ‘alaika ۞ yâ rasûl salâm ‘alaika", "id": "Wahai Nabi, salam sejahtera untukmu; wahai Rasul, salam sejahtera untukmu.", "no": 2},
{"ar": "يَا حَبِيْبْ سَلَامْ عَلَيْكَ ۞ صَلَوَاتُ اللهْ عَلَيْكَ", "lt": "Yâ ḥabîb salâm ‘alaika ۞ shalawâtullâh ‘alaika", "id": "Wahai kekasih, salam sejahtera untukmu; shalawat Allah tercurah untukmu.", "no": 3},
{"ar": "أَشْرَقَ الْبَدْرُ عَلَيْنَا ۞ فَاخْتَفَتْ مِنْهُ الْبُدُوْرُ", "lt": "Asyraqal-badru ‘alainâ ۞ fakhtafat minhul-budûru", "id": "Telah terbit bulan purnama di tengah kami, maka tenggelamlah purnama-purnama lainnya.", "no": 4},
{"ar": "مِثْلَ حُسْنِكْ مَا رَأَيْنَا ۞ قَطُّ يَا وَجْهَ السُّرُوْرِ", "lt": "Mitsla ḥusnik mâ ra'ainâ ۞ qaṭṭu yâ wajhas-surûri", "id": "Belum pernah kami melihat keindahan seperti keindahanmu, wahai wajah yang membawa kegembiraan.", "no": 5},
{"ar": "أَنْتَ شَمْسٌ أَنْتَ بَدْرٌ ۞ أَنْتَ نُوْرٌ فَوْقَ نُوْرِ", "lt": "Anta syamsun anta badrun ۞ anta nûrun fauqa nûri", "id": "Engkau matahari, engkau bulan purnama, engkau cahaya di atas cahaya.", "no": 6},
{"ar": "أَنْتَ إِكْسِيْرٌ وَغَالِيْ ۞ أَنْتَ مِصْبَاحُ الصُّدُوْرِ", "lt": "Anta iksîrun wa ghâlî ۞ anta mishbâḥush-shudûri", "id": "Engkau bagaikan iksir yang amat berharga; engkau pelita hati.", "no": 7},
{"ar": "يَا حَبِيْبِيْ يَا مُحَمَّدْ ۞ يَا عَرُوْسَ الْخَافِقَيْنِ", "lt": "Yâ ḥabîbî yâ muḥammad ۞ yâ ‘arûsal-khâfiqaini", "id": "Wahai kekasihku, wahai Muhammad; wahai pengantin timur dan barat.", "no": 8},
{"ar": "يَا مُؤَيَّدْ يَا مُمَجَّدْ ۞ يَا إِمَامَ الْقِبْلَتَيْنِ", "lt": "Yâ mu'ayyad yâ mumajjad ۞ yâ imâmal-qiblataini", "id": "Wahai yang dikuatkan, wahai yang diagungkan; wahai imam dua kiblat.", "no": 9},
{"ar": "مَنْ رَأَى وَجْهَكَ يَسْعَدْ ۞ يَا كَرِيْمَ الْوَالِدَيْنِ", "lt": "Man ra'â wajhaka yas‘ad ۞ yâ karîmal-wâlidaini", "id": "Siapa yang memandang wajahmu pasti berbahagia, wahai yang mulia kedua orang tuanya.", "no": 10},
{"ar": "حَوْضُكَ الصَّافِي الْمُبَرَّدْ ۞ وِرْدُنَا يَوْمَ النُّشُوْرِ", "lt": "Ḥaudlukash-shâfil-mubarrad ۞ wirdunâ yauman-nusyûri", "id": "Telagamu yang jernih lagi sejuk menjadi tempat minum kami pada hari kebangkitan.", "no": 11},
{"ar": "مَا رَأَيْنَا الْعِيْسَ حَنَّتْ ۞ بِالسُّرَى إِلَّا إِلَيْكَ", "lt": "Mâ ra'ainal-‘îsa ḥannat ۞ bis-surâ illâ ilaika", "id": "Tidaklah kami melihat unta merindu berjalan di malam hari kecuali kepadamu.", "no": 12},
{"ar": "وَالْغَمَامَةْ قَدْ أَظَلَّتْ ۞ وَالْمَلَا صَلُّوْا عَلَيْكَ", "lt": "Wal-ghamâmah qad adhallat ۞ wal-malâ shallû ‘alaika", "id": "Awan pun menaungimu, dan para malaikat bershalawat kepadamu.", "no": 13},
{"ar": "وَأَتَاكَ الْعُوْدُ يَبْكِيْ ۞ وَتَذَلَّلْ بَيْنَ يَدَيْكَ", "lt": "Wa atâkal-‘ûdu yabkî ۞ wa tadzallal baina yadaika", "id": "Batang kurma datang kepadamu sambil menangis, dan merendahkan diri di hadapanmu.", "no": 14},
{"ar": "وَاسْتَجَارَتْ يَا حَبِيْبِيْ ۞ عِنْدَكَ الظَّبْيُ النَّفُوْرُ", "lt": "Wastajârat yâ ḥabîbî ۞ ‘indakadh-dhabyun-nafûru", "id": "Wahai kekasihku, kijang yang lari pun memohon perlindungan kepadamu.", "no": 15},
{"ar": "عِنْدَمَا شَدُّوا الْمَحَامِلْ ۞ وَتَنَادَوْا لِلرَّحِيْلِ", "lt": "‘Indamâ syaddul-maḥâmil ۞ wa tanâdau lir-raḥîli", "id": "Ketika mereka mengikat sekedup unta dan saling memanggil untuk berangkat,", "no": 16},
{"ar": "جِئْتُهُمْ وَالدَّمْعُ سَائِلْ ۞ قُلْتُ قِفْ لِيْ يَا دَلِيْلُ", "lt": "Ji'tuhum wad-dam‘u sâ'il ۞ qultu qif lî yâ dalîlu", "id": "aku mendatangi mereka dengan air mata berlinang, aku berkata: Berhentilah sebentar untukku, wahai penunjuk jalan.", "no": 17},
{"ar": "وَتَحَمَّلْ لِيْ رَسَائِلْ ۞ أَيُّهَا الشَّوْقُ الْجَزِيْلُ", "lt": "Wa taḥammal lî rasâ'il ۞ ayyuhasy-syauqul-jazîlu", "id": "Bawakanlah surat-suratku, wahai kerinduan yang amat besar,", "no": 18},
{"ar": "نَحْوَ هَاتِيْكَ الْمَنَازِلْ ۞ فِي الْعَشِيِّ وَالْبُكُوْرِ", "lt": "Naḥwa hâtîkal-manâzil ۞ fil-‘asyiyyi wal-bukûri", "id": "menuju tempat-tempat itu, di waktu petang dan pagi.", "no": 19},
{"ar": "كُلُّ مَنْ فِي الْكَوْنِ هَامُوْا ۞ فِيْكَ يَا بَاهِي الْجَبِيْنِ", "lt": "Kullu man fil-kauni hâmû ۞ fîka yâ bâhil-jabîni", "id": "Semua yang ada di alam semesta terpesona olehmu, wahai yang bercahaya dahinya.", "no": 20},
{"ar": "وَلَهُمْ فِيْكَ غَرَامُ ۞ وَاشْتِيَاقٌ وَحَنِيْنُ", "lt": "Wa lahum fîka gharâmu ۞ wasytiyâqun wa ḥanînu", "id": "Mereka sangat mencintaimu, merindukanmu, dan mendambakanmu.", "no": 21},
{"ar": "فِيْ مَعَانِيْكَ الْأَنَامُ ۞ قَدْ تَبَدَّتْ حَائِرِيْنَ", "lt": "Fî ma‘ânîkal-anâmu ۞ qad tabaddat ḥâ'irîna", "id": "Dalam (memahami) makna-makna dirimu, manusia tampak kebingungan.", "no": 22},
{"ar": "أَنْتَ لِلرُّسْلِ خِتَامُ ۞ أَنْتَ لِلْمَوْلَى شَكُوْرُ", "lt": "Anta lir-rusli khitâmu ۞ anta lil-maulâ syakûru", "id": "Engkau penutup para rasul, engkau hamba yang sangat bersyukur kepada Tuhan.", "no": 23},
{"ar": "عَبْدُكَ الْمِسْكِيْنُ يَرْجُوْ ۞ فَضْلَكَ الْجَمَّ الْغَفِيْرَ", "lt": "‘Abdukal-miskînu yarjû ۞ fadllakal-jammal-ghafîra", "id": "Hambamu yang miskin ini mengharapkan karuniamu yang melimpah ruah.", "no": 24},
{"ar": "فِيْكَ قَدْ أَحْسَنْتُ ظَنِّيْ ۞ يَا بَشِيْرُ يَا نَذِيْرُ", "lt": "Fîka qad aḥsantu dhannî ۞ yâ basyîru yâ nadzîru", "id": "Kepadamu aku berbaik sangka, wahai pembawa kabar gembira, wahai pemberi peringatan.", "no": 25},
{"ar": "فَأَغِثْنِيْ وَأَجِرْنِيْ ۞ يَا مُجِيْرُ مِنَ السَّعِيْرِ", "lt": "Fa aghitsnî wa ajirnî ۞ yâ mujîru minas-sa‘îri", "id": "Tolonglah aku dan lindungilah aku, wahai pelindung dari api neraka Sa‘ir.", "no": 26},
{"ar": "يَا غِيَاثِيْ يَا مَلَاذِيْ ۞ فِيْ مُهِمَّاتِ الْأُمُوْرِ", "lt": "Yâ ghiyâtsî yâ malâdzî ۞ fî muhimmâtil-umûri", "id": "Wahai penolongku, wahai tempat berlindungku dalam urusan-urusan yang penting.", "no": 27},
{"ar": "سَعِدَ عَبْدٌ قَدْ تَمَلّٰى ۞ وَانْجَلٰى عَنْهُ الْحَزِيْنُ", "lt": "Sa‘ida ‘abdun qad tamallâ ۞ wanjalâ ‘anhul-ḥazînu", "id": "Berbahagialah hamba yang telah puas (memandangmu), dan hilanglah darinya segala kesedihan.", "no": 28},
{"ar": "فِيْكَ يَا بَدْرُ تَجَلّٰى ۞ فَلَكَ الْوَصْفُ الْحَسِيْنُ", "lt": "Fîka yâ badru tajallâ ۞ falakal-washful-ḥasînu", "id": "Padamu, wahai purnama, tampak segala keindahan; milikmu sifat-sifat yang indah.", "no": 29},
{"ar": "لَيْسَ أَزْكٰى مِنْكَ أَصْلًا ۞ قَطُّ يَا جَدَّ الْحُسَيْنِ", "lt": "Laisa azkâ minka ashlan ۞ qaṭṭu yâ jaddal-ḥusaini", "id": "Tak ada yang lebih suci asal-usulnya daripadamu, wahai kakek Husain.", "no": 30},
{"ar": "فَعَلَيْكَ اللهُ صَلّٰى ۞ دَائِمًا طُوْلَ الدُّهُوْرِ", "lt": "Fa‘alaikallâhu shallâ ۞ dâ'iman ṭûlad-duhûri", "id": "Semoga Allah melimpahkan shalawat kepadamu selamanya sepanjang masa.", "no": 31},
{"ar": "يَا وَلِيَّ الْحَسَنَاتِ ۞ يَا رَفِيْعَ الدَّرَجَاتِ", "lt": "Yâ waliyyal-ḥasanâti ۞ yâ rafî‘ad-darajâti", "id": "Wahai (Allah) Pemilik segala kebaikan, wahai Yang Mahatinggi derajat-Nya,", "no": 32},
{"ar": "كَفِّرْ عَنِّي الذُّنُوْبَ ۞ وَاغْفِرْ عَنِّي السَّيِّئَاتِ", "lt": "Kaffir ‘annidz-dzunûba ۞ waghfir ‘annis-sayyi'âti", "id": "hapuskanlah dosa-dosaku dan ampunilah kesalahan-kesalahanku.", "no": 33},
{"ar": "أَنْتَ غَفَّارُ الْخَطَايَا ۞ وَالذُّنُوْبِ الْمُوْبِقَاتِ", "lt": "Anta ghaffârul-khaṭâyâ ۞ wadz-dzunûbil-mûbiqâti", "id": "Engkaulah Pengampun segala kesalahan dan dosa-dosa yang membinasakan.", "no": 34},
{"ar": "أَنْتَ سَتَّارُ الْمَسَاوِيْ ۞ وَمُقِيْلُ الْعَثَرَاتِ", "lt": "Anta sattârul-masâwî ۞ wa muqîlul-‘atsarâti", "id": "Engkaulah Penutup segala keburukan dan Pemaaf segala ketergelinciran.", "no": 35},
{"ar": "عَالِمُ السِّرِّ وَأَخْفٰى ۞ مُسْتَجِيْبُ الدَّعَوَاتِ", "lt": "‘Âlimus-sirri wa akhfâ ۞ mustajîbud-da‘awâti", "id": "Yang mengetahui rahasia dan yang lebih tersembunyi, Yang mengabulkan doa-doa.", "no": 36},
{"ar": "رَبِّ فَارْحَمْنَا جَمِيْعًا ۞ وَامْحُ عَنَّا السَّيِّئَاتِ", "lt": "Rabbi farḥamnâ jamî‘an ۞ wamḥu ‘annas-sayyi'âti", "id": "Wahai Tuhanku, rahmatilah kami semua, dan hapuskanlah keburukan-keburukan kami.", "no": 37},
{"ar": "رَبِّ فَارْحَمْنَا جَمِيْعًا ۞ بِجَمِيْعِ الصَّالِحَاتِ", "lt": "Rabbi farḥamnâ jamî‘an ۞ bijamî‘ish-shâliḥâti", "id": "Wahai Tuhanku, rahmatilah kami semua dengan (berkah) seluruh amal saleh.", "no": 38},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 39}]},
{judul:"Wa Wulida Shallallahu 'Alaihi wa Sallam",isi:[
{"ar": "وَوُلِدَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَخْتُوْنًا بِيَدِ الْعِنَايَةِ، مَكْحُوْلًا بِكُحْلِ الْهِدَايَةِ، فَأَشْرَقَ بِبَهَائِهِ الْفَضَا، وَتَلَأْلَأَ الْكَوْنُ مِنْ نُوْرِهِ وَأَضَا", "lt": "Wa wulida shallallâhu ‘alaihi wa sallama makhtûnan biyadil-‘inâyah, makḥûlan bikuḥlil-hidâyah, fa'asyraqa bibahâ'ihil-fadlâ, wa tala'la'al-kaunu min nûrihî wa adlâ", "id": "Beliau ﷺ dilahirkan dalam keadaan telah dikhitan oleh tangan pemeliharaan (Allah), bercelak dengan celak hidayah. Maka angkasa bersinar karena keindahannya, dan alam semesta gemerlap terang oleh cahayanya.", "no": 1},
{"ar": "وَدَخَلَ فِيْ عَقْدِ بَيْعَتِهِ مَنْ بَقِيَ مِنَ الْخَلَائِقِ، كَمَا دَخَلَ فِيْهَا مَنْ مَضٰى، أَوَّلُ فَضِيْلَةِ الْمُعْجِزَاتِ بِخُمُوْدِ نَارِ فَارِسَ وَسُقُوْطِ الشُّرُفَاتِ", "lt": "Wa dakhala fî ‘aqdi bai‘atihî man baqiya minal-khalâ'iqi kamâ dakhala fîhâ man madlâ, awwalu fadlîlatil-mu‘jizâti bikhumûdi nâri fârisa wa suqûṭisy-syurufât", "id": "Makhluk yang masih ada masuk ke dalam ikatan baiatnya, sebagaimana yang telah lalu juga masuk ke dalamnya. Mukjizat pertamanya adalah padamnya api sesembahan Persia dan runtuhnya balkon-balkon istana Kisra.", "no": 2},
{"ar": "وَرُمِيَتِ الشَّيَاطِيْنُ مِنَ السَّمَاءِ بِالشُّهُبِ الْمُحْرِقَاتِ، وَرَجَعَ كُلُّ جَبَّارٍ مِنَ الْجِنِّ وَهُوَ بِصَوْلَةِ سَلْطَنَتِهِ ذَلِيْلٌ خَاضِعٌ، لِمَا تَأَلَّقَ مِنْ سَنَاهُ النُّوْرُ السَّاطِعُ، وَأَشْرَقَ مِنْ بَهَائِهِ الضِّيَاءُ اللَّامِعُ، حَتّٰى عُرِضَ عَلَى الْمَرَاضِعِ", "lt": "Wa rumiyatisy-syayâṭînu minas-samâ'i bisy-syuhubil-muḥriqât, wa raja‘a kullu jabbârin minal-jinni wa huwa bishaulati salṭanatihî dzalîlun khâdli‘, limâ ta'allaqa min sanâhun-nûrus-sâṭi‘, wa asyraqa min bahâ'ihidl-dliyâ'ul-lâmi‘, ḥattâ ‘uridla ‘alal-marâdli‘", "id": "Setan-setan dilempari dari langit dengan bintang-bintang yang membakar. Setiap jin yang sombong kembali dalam keadaan hina dan tunduk di bawah wibawa kekuasaannya, karena cahaya terang yang memancar darinya dan sinar berkilau dari keindahannya, hingga beliau ditawarkan kepada para ibu susuan.", "no": 3},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 4},
{"ar": "قِيْلَ: مَنْ يَكْفُلُ هٰذِهِ الدُّرَّةَ الْيَتِيْمَةَ الَّتِيْ لَا تُوْجَدُ لَهَا قِيْمَةٌ؟ قَالَتِ الطُّيُوْرُ: نَحْنُ نَكْفُلُهُ وَنَغْتَنِمُ هِمَّتَهُ الْعَظِيْمَةَ، قَالَتِ الْوُحُوْشُ: نَحْنُ أَوْلٰى بِذٰلِكَ لِكَيْ نَنَالَ شَرَفَهُ وَتَعْظِيْمَهُ", "lt": "Qîla: man yakfulu hâdzihid-durratal-yatîmatal-latî lâ tûjadu lahâ qîmah? qâlatiṭ-ṭuyûr: naḥnu nakfuluhû wa naghtanimu himmatahul-‘adhîmah, qâlatil-wuḥûsy: naḥnu aulâ bidzâlika likai nanâla syarafahû wa ta‘dhîmah", "id": "Ditanyakan: Siapakah yang akan mengasuh mutiara tunggal yang tak ternilai harganya ini? Burung-burung berkata: Kamilah yang akan mengasuhnya dan meraih semangatnya yang agung. Binatang-binatang liar berkata: Kami lebih berhak, agar kami memperoleh kemuliaan dan keagungannya.", "no": 5},
{"ar": "قِيْلَ: يَا مَعْشَرَ الْأُمَمِ اسْكُنُوْا، فَإِنَّ اللهَ قَدْ حَكَمَ فِيْ سَابِقِ حِكْمَتِهِ الْقَدِيْمَةِ، بِأَنَّ نَبِيَّهُ مُحَمَّدًا صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَكُوْنُ رَضِيْعًا لِحَلِيْمَةَ الْحَلِيْمَةِ", "lt": "Qîla: yâ ma‘syaral-umamis-kunû, fa'innallâha qad ḥakama fî sâbiqi ḥikmatihil-qadîmah, bi'anna nabiyyahû muḥammadan shallallâhu ‘alaihi wa sallama yakûnu radlî‘an liḥalîmatal-ḥalîmah", "id": "Dikatakan: Wahai seluruh umat, tenanglah! Sesungguhnya Allah telah menetapkan dalam hikmah-Nya yang terdahulu bahwa Nabi-Nya, Muhammad ﷺ, akan menjadi anak susuan Halimah yang penyabar.", "no": 6},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 7},
{"ar": "ثُمَّ أَعْرَضَ عَنْهُ مَرَاضِعُ الْإِنْسِ لِمَا سَبَقَ فِيْ طَيِّ الْغَيْبِ مِنَ السَّعَادَةِ لِحَلِيْمَةَ بِنْتِ أَبِيْ ذُؤَيْبٍ، فَلَمَّا وَقَعَ نَظَرُهَا عَلَيْهِ بَادَرَتْ مُسْرِعَةً إِلَيْهِ، وَوَضَعَتْهُ فِيْ حِجْرِهَا، وَضَمَّتْهُ إِلَى صَدْرِهَا", "lt": "Tsumma a‘radla ‘anhu marâdli‘ul-insi limâ sabaqa fî ṭayyil-ghaibi minas-sa‘âdati liḥalîmata binti abî dzu'aib, falammâ waqa‘a nadharuhâ ‘alaihi bâdarat musri‘atan ilaih, wa wadla‘athu fî ḥijrihâ, wa dlammathu ilâ shadrihâ", "id": "Kemudian para ibu susuan dari kalangan manusia berpaling darinya, karena telah ditetapkan dalam lipatan gaib kebahagiaan itu untuk Halimah binti Abi Dzu'aib. Ketika pandangannya jatuh kepada beliau, ia bergegas menghampirinya, meletakkannya di pangkuannya, dan mendekapnya ke dadanya.", "no": 8},
{"ar": "فَهَشَّ لَهَا مُتَبَسِّمًا، فَخَرَجَ مِنْ ثَغْرِهِ نُوْرٌ لَحِقَ بِالسَّمَاءِ، فَحَمَلَتْهُ إِلَى رَحْلِهَا، وَارْتَحَلَتْ بِهِ إِلَى أَهْلِهَا، فَلَمَّا وَصَلَتْ بِهِ إِلَى مُقَامِهَا، عَايَنَتْ بَرَكَتَهُ عَلَى أَغْنَامِهَا", "lt": "Fahasysya lahâ mutabassimâ, fakharaja min tsaghrihî nûrun laḥiqa bis-samâ', faḥamalathu ilâ raḥlihâ, wartaḥalat bihî ilâ ahlihâ, falammâ washalat bihî ilâ muqâmihâ, ‘âyanat barakatahû ‘alâ aghnâmihâ", "id": "Beliau pun tersenyum ceria kepadanya, maka keluarlah dari mulutnya cahaya yang menjulang sampai ke langit. Halimah membawanya ke tunggangannya dan berangkat bersamanya menuju keluarganya. Setibanya di tempat tinggalnya, ia menyaksikan keberkahan beliau pada kambing-kambingnya.", "no": 9},
{"ar": "وَكَانَتْ كُلَّ يَوْمٍ تَرٰى مِنْهُ بُرْهَانًا، وَتَرْفَعُ لَهُ قَدْرًا وَشَانًا، حَتّٰى انْدَرَجَ فِيْ حُلَّةِ اللُّطْفِ وَالْأَمَانِ، وَدَخَلَ بَيْنَ إِخْوَتِهِ مَعَ الصِّبْيَانِ", "lt": "Wa kânat kulla yaumin tarâ minhu burhânâ, wa tarfa‘u lahû qadran wa syânâ, ḥattandaraja fî ḥullatil-luṭfi wal-amân, wa dakhala baina ikhwatihî ma‘ash-shibyân", "id": "Setiap hari Halimah melihat bukti (keistimewaan) darinya, dan semakin tinggi kedudukan serta martabatnya di matanya, hingga beliau tumbuh dalam balutan kasih sayang dan rasa aman, dan bergaul dengan saudara-saudaranya bersama anak-anak lainnya.", "no": 10},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 11}]},
{judul:"Fa Bainamal Habib: Pembelahan Dada",isi:[
{"ar": "فَبَيْنَمَا الْحَبِيْبُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ نَاءٍ عَنِ الْأَوْطَانِ، إِذْ أَقْبَلَ عَلَيْهِ ثَلَاثَةُ نَفَرٍ كَأَنَّ وُجُوْهَهُمُ الشَّمْسُ وَالْقَمَرُ، فَانْطَلَقَ الصِّبْيَانُ هَرَبًا، وَوَقَفَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُتَعَجِّبًا", "lt": "Fabainamal-ḥabîbu shallallâhu ‘alaihi wa sallama dzâta yaumin nâ'in ‘anil-auṭân, idz aqbala ‘alaihi tsalâtsatu nafarin ka'anna wujûhahumusy-syamsu wal-qamar, fanṭalaqash-shibyânu haraban, wa waqafan-nabiyyu shallallâhu ‘alaihi wa sallama muta‘ajjibâ", "id": "Suatu hari, ketika sang kekasih ﷺ berada jauh dari perkampungan, datanglah kepadanya tiga orang yang wajahnya bagaikan matahari dan bulan. Anak-anak lain pun lari ketakutan, sedangkan Nabi ﷺ berdiri dengan takjub.", "no": 1},
{"ar": "فَأَضْجَعُوْهُ عَلَى الْأَرْضِ إِضْجَاعًا خَفِيْفًا، وَشَقُّوْا بَطْنَهُ شَقًّا لَطِيْفًا، ثُمَّ أَخْرَجُوْا قَلْبَ سَيِّدِ وَلَدِ عَدْنَانَ، وَشَرَحُوْهُ بِسِكِّيْنِ الْإِحْسَانِ، وَنَزَعُوْا مِنْهُ حَظَّ الشَّيْطَانِ", "lt": "Fa adlja‘ûhu ‘alal-ardli idljâ‘an khafîfâ, wa syaqqû baṭnahû syaqqan laṭîfâ, tsumma akhrajû qalba sayyidi waladi ‘adnân, wa syaraḥûhu bisikkînil-iḥsân, wa naza‘û minhu ḥadhdhasy-syaiṭân", "id": "Mereka membaringkannya di atas tanah dengan perlahan, lalu membelah perutnya dengan lembut. Kemudian mereka mengeluarkan hati pemimpin keturunan Adnan, membedahnya dengan pisau kebaikan, dan mencabut darinya bagian setan.", "no": 2},
{"ar": "وَمَلَئُوْهُ بِالْحِلْمِ وَالْعِلْمِ وَالْيَقِيْنِ وَالرِّضْوَانِ، وَأَعَادُوْهُ إِلَى مَكَانِهِ، فَقَامَ الْحَبِيْبُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَوِيًّا كَمَا كَانَ", "lt": "Wa mala'ûhu bil-ḥilmi wal-‘ilmi wal-yaqîni war-ridlwân, wa a‘âdûhu ilâ makânih, faqâmal-ḥabîbu shallallâhu ‘alaihi wa sallama sawiyyan kamâ kân", "id": "Mereka memenuhinya dengan kesabaran, ilmu, keyakinan, dan keridaan, lalu mengembalikannya ke tempatnya. Maka sang kekasih ﷺ berdiri kembali dalam keadaan utuh seperti semula.", "no": 3},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 4},
{"ar": "فَقَالَتِ الْمَلَائِكَةُ: يَا حَبِيْبَ الرَّحْمٰنِ، لَوْ عَلِمْتَ مَا يُرَادُ بِكَ مِنَ الْخَيْرِ، لَعَرَفْتَ قَدْرَ مَنْزِلَتِكَ عَلَى الْغَيْرِ، وَازْدَدْتَ فَرَحًا وَسُرُوْرًا، وَبَهْجَةً وَنُوْرًا", "lt": "Faqâlatil-malâ'ikah: yâ ḥabîbar-raḥmân, lau ‘alimta mâ yurâdu bika minal-khair, la‘arafta qadra manzilatika ‘alal-ghair, wazdadta faraḥan wa surûrâ, wa bahjatan wa nûrâ", "id": "Para malaikat berkata: Wahai kekasih Ar-Rahman, seandainya engkau mengetahui kebaikan yang dikehendaki untukmu, niscaya engkau akan mengetahui ketinggian kedudukanmu di atas yang lain, dan engkau akan bertambah gembira, bahagia, ceria, dan bercahaya.", "no": 5},
{"ar": "يَا مُحَمَّدُ أَبْشِرْ، فَقَدْ نُشِرَتْ فِي الْكَائِنَاتِ أَعْلَامُ عُلُوْمِكَ، وَتَبَاشَرَتِ الْمَخْلُوْقَاتُ بِقُدُوْمِكَ، وَلَمْ يَبْقَ شَيْءٌ مِمَّا خَلَقَ اللهُ إِلَّا جَاءَ لِأَمْرِكَ طَائِعًا، وَلِمَقَالَتِكَ سَامِعًا", "lt": "Yâ muḥammadu absyir, faqad nusyirat fil-kâ'inâti a‘lâmu ‘ulûmik, wa tabâsyaratil-makhlûqâtu biqudûmik, wa lam yabqa syai'un mimmâ khalaqallâhu illâ jâ'a li'amrika ṭâ'i‘â, wa limaqâlatika sâmi‘â", "id": "Wahai Muhammad, bergembiralah! Panji-panji ilmumu telah dikibarkan di seluruh alam, seluruh makhluk bersuka cita atas kedatanganmu, dan tidak ada satu pun ciptaan Allah kecuali datang dengan patuh kepada perintahmu dan mendengar ucapanmu.", "no": 6},
{"ar": "فَسَيَأْتِيْكَ الْبَعِيْرُ بِذِمَامِكَ يَسْتَجِيْرُ، وَالضَّبُّ وَالْغَزَالَةُ يَشْهَدَانِ لَكَ بِالرِّسَالَةِ، وَالْقَمَرُ وَالشَّجَرُ وَالذِّيْبُ يَنْطِقُوْنَ بِنُبُوَّتِكَ عَنْ قَرِيْبٍ", "lt": "Fasaya'tîkal-ba‘îru bidzimâmika yastajîr, wadl-dlabbu wal-ghazâlatu yasyhadâni laka bir-risâlah, wal-qamaru wasy-syajaru wadz-dzi'bu yanṭiqûna binubuwwatika ‘an qarîb", "id": "Kelak seekor unta akan datang kepadamu memohon perlindungan, biawak dan kijang akan bersaksi atas kerasulanmu, dan bulan, pohon, serta serigala akan mengucapkan kenabianmu dalam waktu dekat.", "no": 7},
{"ar": "وَمَرْكَبُكَ الْبُرَاقُ إِلَى جَمَالِكَ مُشْتَاقٌ، وَجِبْرِيْلُ شَاوُوْشُ مَمْلَكَتِكَ قَدْ أَعْلَنَ بِذِكْرِكَ فِي الْآفَاقِ، وَالْقَمَرُ مَأْمُوْرٌ لَكَ بِالْاِنْشِقَاقِ، وَكُلُّ مَنْ فِي الْكَوْنِ مُتَشَوِّقٌ لِظُهُوْرِكَ، مُنْتَظِرٌ لِإِشْرَاقِ نُوْرِكَ", "lt": "Wa markabukal-burâqu ilâ jamâlika musytâq, wa jibrîlu syâwûsyu mamlakatika qad a‘lana bidzikrika fil-âfâq, wal-qamaru ma'mûrun laka bil-insyiqâq, wa kullu man fil-kauni mutasyawwiqun lidhuhûrik, muntadhirun li'isyrâqi nûrik", "id": "Kendaraanmu, Buraq, rindu kepada keindahanmu. Jibril, pengawal kerajaanmu, telah mengumumkan namamu di seluruh penjuru. Bulan diperintahkan untuk terbelah bagimu, dan semua yang ada di alam semesta merindukan kemunculanmu serta menantikan terbitnya cahayamu.", "no": 8},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 9},
{"ar": "فَبَيْنَمَا الْحَبِيْبُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُنْصِتٌ لِسَمَاعِ تِلْكَ الْأَشْبَاحِ، وَوَجْهُهُ مُتَهَلِّلٌ كَنُوْرِ الصَّبَاحِ، إِذْ أَقْبَلَتْ حَلِيْمَةُ مُعْلِنَةً بِالصِّيَاحِ، تَقُوْلُ: وَاغَرِيْبَاهُ", "lt": "Fabainamal-ḥabîbu shallallâhu ‘alaihi wa sallama munshitun lisamâ‘i tilkal-asybâḥ, wa wajhuhû mutahallilun kanûrish-shabâḥ, idz aqbalat ḥalîmatu mu‘linatan bish-shiyâḥ, taqûlu: wâgharîbâh", "id": "Ketika sang kekasih ﷺ sedang menyimak (ucapan) sosok-sosok itu dengan wajah berseri seperti cahaya pagi, tiba-tiba datanglah Halimah sambil berteriak: Duhai anakku yang terasing!", "no": 10},
{"ar": "فَقَالَتِ الْمَلَائِكَةُ: يَا مُحَمَّدُ مَا أَنْتَ بِغَرِيْبٍ، بَلْ أَنْتَ مِنَ اللهِ قَرِيْبٌ، وَأَنْتَ لَهُ صَفِيٌّ وَحَبِيْبٌ. قَالَتْ حَلِيْمَةُ: وَاوَحِيْدَاهُ، فَقَالَتِ الْمَلَائِكَةُ: يَا مُحَمَّدُ مَا أَنْتَ بِوَحِيْدٍ، بَلْ أَنْتَ صَاحِبُ التَّأْيِيْدِ، وَأَنِيْسُكَ الْحَمِيْدُ الْمَجِيْدُ، وَإِخْوَانُكَ مِنَ الْمَلَائِكَةِ وَأَهْلِ التَّوْحِيْدِ", "lt": "Faqâlatil-malâ'ikah: yâ muḥammadu mâ anta bigharîb, bal anta minallâhi qarîb, wa anta lahû shafiyyun wa ḥabîb. Qâlat ḥalîmah: wâwaḥîdâh, faqâlatil-malâ'ikah: yâ muḥammadu mâ anta biwaḥîd, bal anta shâḥibut-ta'yîd, wa anîsukal-ḥamîdul-majîd, wa ikhwânuka minal-malâ'ikati wa ahlit-tauḥîd", "id": "Para malaikat berkata: Wahai Muhammad, engkau bukanlah orang yang terasing, bahkan engkau dekat dengan Allah, engkau adalah pilihan dan kekasih-Nya. Halimah berkata: Duhai anakku yang sebatang kara! Para malaikat berkata: Wahai Muhammad, engkau tidaklah sendiri, bahkan engkau pemilik pertolongan (Allah); teman setiamu adalah Yang Maha Terpuji lagi Maha Mulia, dan saudara-saudaramu adalah para malaikat dan ahli tauhid.", "no": 11},
{"ar": "قَالَتْ حَلِيْمَةُ: وَايَتِيْمَاهُ، فَقَالَتِ الْمَلَائِكَةُ: لِلّٰهِ دَرُّكَ مِنْ يَتِيْمٍ، فَإِنَّ قَدْرَكَ عِنْدَ اللهِ عَظِيْمٌ", "lt": "Qâlat ḥalîmah: wâyatîmâh, faqâlatil-malâ'ikah: lillâhi darruka min yatîm, fa'inna qadraka ‘indallâhi ‘adhîm", "id": "Halimah berkata: Duhai anakku yang yatim! Para malaikat berkata: Betapa istimewanya engkau sebagai anak yatim, sungguh kedudukanmu di sisi Allah amatlah agung.", "no": 12},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 13},
{"ar": "فَلَمَّا رَأَتْهُ حَلِيْمَةُ سَالِمًا مِنَ الْأَهْوَالِ، رَجَعَتْ بِهِ مَسْرُوْرَةً إِلَى الْأَطْلَالِ، ثُمَّ قَصَّتْ خَبَرَهُ عَلَى بَعْضِ الْكُهَّانِ، وَأَعَادَتْ عَلَيْهِ مَا تَمَّ مِنْ أَمْرِهِ وَمَا كَانَ", "lt": "Falammâ ra'athu ḥalîmatu sâliman minal-ahwâl, raja‘at bihî masrûratan ilal-aṭlâl, tsumma qashshat khabarahû ‘alâ ba‘dlil-kuhhân, wa a‘âdat ‘alaihi mâ tamma min amrihî wa mâ kân", "id": "Ketika Halimah melihatnya selamat dari peristiwa yang menakutkan itu, ia membawanya pulang dengan gembira ke perkampungan. Kemudian ia menceritakan kisahnya kepada seorang dukun, dan mengulangi semua yang telah terjadi padanya.", "no": 14},
{"ar": "فَقَالَ لَهُ الْكَاهِنُ: يَا ابْنَ زَمْزَمَ وَالْمَقَامِ، وَالرُّكْنِ وَالْبَيْتِ الْحَرَامِ، أَفِي الْيَقْظَةِ رَأَيْتَ هٰذَا أَمْ فِي الْمَنَامِ؟ فَقَالَ وَحُرْمَةِ الْمَلِكِ الْعَلَّامِ، شَاهَدْتُهُمْ كِفَاحًا لَا أَشُكُّ فِيْ ذٰلِكَ وَلَا أُضَامُ", "lt": "Faqâla lahul-kâhin: yabna zamzama wal-maqâm, war-rukni wal-baitil-ḥarâm, afil-yaqdhati ra'aita hâdzâ am fil-manâm? faqâla: wa ḥurmatil-malikil-‘allâm, syâhadtuhum kifâḥan lâ asyukku fî dzâlika wa lâ udlâm", "id": "Dukun itu bertanya kepada beliau: Wahai putra Zamzam dan Maqam (Ibrahim), Rukun dan Baitul Haram, apakah engkau melihat ini dalam keadaan terjaga atau dalam mimpi? Beliau menjawab: Demi kemuliaan Raja Yang Maha Mengetahui, aku menyaksikan mereka secara langsung, aku tidak ragu dan tidak tertipu.", "no": 15},
{"ar": "فَقَالَ لَهُ الْكَاهِنُ: أَبْشِرْ أَيُّهَا الْغُلَامُ، فَأَنْتَ صَاحِبُ الْأَعْلَامِ، وَنُبُوَّتُكَ لِلْأَنْبِيَاءِ قُفْلٌ وَخِتَامٌ، عَلَيْكَ يَنْزِلُ جِبْرِيْلُ، وَعَلَى بِسَاطِ الْقُدْسِ يُخَاطِبُكَ الْجَلِيْلُ", "lt": "Faqâla lahul-kâhin: absyir ayyuhal-ghulâm, fa'anta shâḥibul-a‘lâm, wa nubuwwatuka lil-anbiyâ'i qufulun wa khitâm, ‘alaika yanzilu jibrîl, wa ‘alâ bisâṭil-qudsi yukhâṭibukal-jalîl", "id": "Dukun itu berkata: Bergembiralah wahai anak muda, engkaulah pemilik panji-panji, kenabianmu adalah kunci dan penutup bagi para nabi. Kepadamu Jibril akan turun, dan di atas hamparan kesucian Yang Mahaagung akan berbicara kepadamu.", "no": 16},
{"ar": "وَمَنْ ذَا الَّذِيْ يَحْصُرُ مَا حَوَيْتَ مِنَ التَّفْضِيْلِ، وَعَنْ بَعْضِ وَصْفِ مَعْنَاكَ يَقْصُرُ لِسَانُ الْمَادِحِ الْمُطِيْلِ", "lt": "Wa man dzal-ladzî yaḥshuru mâ ḥawaita minat-tafdlîl, wa ‘an ba‘dli washfi ma‘nâka yaqshuru lisânul-mâdiḥil-muṭîl", "id": "Siapakah yang mampu menghitung keutamaan yang engkau miliki? Untuk menyifati sebagian maknamu saja, lisan pemuji yang panjang lebar pun tak sanggup.", "no": 17},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 18}]},
{judul:"Wa Kana Ahsanan Nasi Khalqan wa Khuluqan",isi:[
{"ar": "وَكَانَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَحْسَنَ النَّاسِ خَلْقًا وَخُلُقًا، وَأَهْدَاهُمْ إِلَى الْحَقِّ طُرُقًا، كَانَ خُلُقُهُ الْقُرْآنَ، وَشِيْمَتُهُ الْغُفْرَانَ، يَنْصَحُ لِلْإِنْسَانِ، وَيَفْسَحُ فِي الْإِحْسَانِ", "lt": "Wa kâna shallallâhu ‘alaihi wa sallama aḥsanan-nâsi khalqan wa khuluqâ, wa ahdâhum ilal-ḥaqqi ṭuruqâ, kâna khuluquhul-qur'ân, wa syîmatuhul-ghufrân, yanshaḥu lil-insân, wa yafsaḥu fil-iḥsân", "id": "Beliau ﷺ adalah manusia yang paling indah rupa dan akhlaknya, dan paling lurus jalannya menuju kebenaran. Akhlaknya adalah Al-Qur'an, tabiatnya pemaaf, menasihati manusia, dan lapang dalam berbuat kebaikan.", "no": 1},
{"ar": "وَيَعْفُوْ عَنِ الذَّنْبِ إِذَا كَانَ فِيْ حَقِّهِ وَسَبَبِهِ، وَإِذَا ضُيِّعَ حَقُّ اللهِ لَمْ يَقُمْ أَحَدٌ لِغَضَبِهِ، مَنْ رَآهُ بَدِيْهَةً هَابَهُ، وَإِذَا دَعَاهُ الْمِسْكِيْنُ أَجَابَهُ", "lt": "Wa ya‘fû ‘anidz-dzanbi idzâ kâna fî ḥaqqihî wa sababih, wa idzâ dluyyi‘a ḥaqqullâhi lam yaqum aḥadun lighadlabih, man ra'âhu badîhatan hâbah, wa idzâ da‘âhul-miskînu ajâbah", "id": "Beliau memaafkan kesalahan bila menyangkut hak dan urusan pribadinya; namun bila hak Allah diabaikan, tak seorang pun mampu menahan kemarahannya. Siapa yang melihatnya secara tiba-tiba akan segan kepadanya, dan bila orang miskin memanggilnya, beliau memenuhinya.", "no": 2},
{"ar": "يَقُوْلُ الْحَقَّ وَلَوْ كَانَ مُرًّا، وَلَا يُضْمِرُ لِمُسْلِمٍ غِشًّا وَلَا ضُرًّا، مَنْ نَظَرَ فِيْ وَجْهِهِ عَلِمَ أَنَّهُ لَيْسَ بِوَجْهِ كَذَّابٍ، وَكَانَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَيْسَ بِغَمَّازٍ وَلَا عَيَّابٍ", "lt": "Yaqûlul-ḥaqqa wa lau kâna murrâ, wa lâ yudlmiru limuslimin ghisysyan wa lâ dlurrâ, man nadhara fî wajhihî ‘alima annahû laisa biwajhi kadzdzâb, wa kâna shallallâhu ‘alaihi wa sallama laisa bighammâzin wa lâ ‘ayyâb", "id": "Beliau mengatakan kebenaran walaupun pahit, dan tidak menyimpan niat menipu atau mencelakai seorang muslim pun. Siapa yang memandang wajahnya akan tahu bahwa itu bukanlah wajah seorang pendusta. Beliau ﷺ bukanlah pengumpat dan bukan pencela.", "no": 3},
{"ar": "إِذَا سُرَّ فَكَأَنَّ وَجْهَهُ قِطْعَةُ قَمَرٍ، وَإِذَا كَلَّمَ النَّاسَ فَكَأَنَّمَا يَجْنُوْنَ مِنْ كَلَامِهِ أَحْلٰى ثَمَرٍ، وَإِذَا ابْتَسَمَ تَبَسَّمَ عَنْ مِثْلِ حَبِّ الْغَمَامِ، وَإِذَا تَكَلَّمَ فَكَأَنَّ الدُّرَّ يَسْقُطُ مِنْ ذٰلِكَ الْكَلَامِ", "lt": "Idzâ surra faka'anna wajhahû qiṭ‘atu qamar, wa idzâ kallaman-nâsa faka'annamâ yajnûna min kalâmihî aḥlâ tsamar, wa idzab-tasama tabassama ‘an mitsli ḥabbil-ghamâm, wa idzâ takallama faka'annad-durra yasquṭu min dzâlikal-kalâm", "id": "Bila beliau gembira, wajahnya bagaikan belahan bulan. Bila berbicara kepada manusia, seakan-akan mereka memetik buah yang paling manis dari ucapannya. Bila tersenyum, tampak giginya bagaikan butiran embun, dan bila berbicara seolah-olah mutiara berjatuhan dari ucapannya.", "no": 4},
{"ar": "وَإِذَا تَحَدَّثَ فَكَأَنَّ الْمِسْكَ يَخْرُجُ مِنْ فِيْهِ، وَإِذَا مَرَّ بِطَرِيْقٍ عُرِفَ مِنْ طِيْبِهِ أَنَّهُ قَدْ مَرَّ فِيْهِ، وَإِذَا جَلَسَ فِيْ مَجْلِسٍ بَقِيَ طِيْبُهُ فِيْهِ أَيَّامًا وَإِنْ تَغَيَّبَ، وَيُوْجَدُ مِنْهُ أَحْسَنُ طِيْبٍ وَإِنْ لَمْ يَكُنْ قَدْ تَطَيَّبَ", "lt": "Wa idzâ taḥaddatsa faka'annal-miska yakhruju min fîh, wa idzâ marra biṭarîqin ‘urifa min ṭîbihî annahû qad marra fîh, wa idzâ jalasa fî majlisin baqiya ṭîbuhû fîhi ayyâman wa in taghayyab, wa yûjadu minhu aḥsanu ṭîbin wa in lam yakun qad taṭayyab", "id": "Bila berbicara, seakan-akan kesturi keluar dari mulutnya. Bila melewati suatu jalan, dari wanginya diketahui bahwa beliau telah lewat di sana. Bila duduk di suatu majelis, wanginya tetap tertinggal di sana berhari-hari meski beliau telah pergi. Darinya tercium wangi terbaik walaupun beliau tidak memakai wewangian.", "no": 5},
{"ar": "وَإِذَا مَشٰى بَيْنَ أَصْحَابِهِ فَكَأَنَّهُ الْقَمَرُ بَيْنَ النُّجُوْمِ الزُّهَرِ، وَإِذَا أَقْبَلَ لَيْلًا فَكَأَنَّ النَّاسَ مِنْ نُوْرِهِ فِيْ أَوَانِ الظُّهْرِ", "lt": "Wa idzâ masyâ baina ash-ḥâbihî faka'annahul-qamaru bainan-nujûmiz-zuhar, wa idzâ aqbala lailan faka'annan-nâsa min nûrihî fî awânidh-dhuhr", "id": "Bila berjalan di antara para sahabatnya, beliau bagaikan bulan di antara bintang-bintang yang bersinar. Bila datang di malam hari, seakan-akan manusia berada di waktu tengah hari karena cahayanya.", "no": 6},
{"ar": "وَكَانَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَجْوَدَ بِالْخَيْرِ مِنَ الرِّيْحِ الْمُرْسَلَةِ، وَكَانَ يَرْفُقُ بِالْيَتِيْمِ وَالْأَرْمَلَةِ، قَالَ بَعْضُ وَاصِفِيْهِ: مَا رَأَيْتُ مِنْ ذِيْ لِمَّةٍ سَوْدَاءَ فِيْ حُلَّةٍ حَمْرَاءَ أَحْسَنَ مِنْ رَسُوْلِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ", "lt": "Wa kâna shallallâhu ‘alaihi wa sallama ajwada bil-khairi minar-rîḥil-mursalah, wa kâna yarfuqu bil-yatîmi wal-armalah, qâla ba‘dlu wâshifîh: mâ ra'aitu min dzî limmatin saudâ'a fî ḥullatin ḥamrâ'a aḥsana min rasûlillâhi shallallâhu ‘alaihi wa sallam", "id": "Beliau ﷺ lebih dermawan dalam kebaikan daripada angin yang berembus, dan beliau sangat lembut kepada anak yatim dan janda. Sebagian orang yang menyifatinya berkata: Aku tidak pernah melihat seorang pun yang berambut hitam sebahu dengan pakaian merah yang lebih tampan daripada Rasulullah ﷺ.", "no": 7},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 8},
{"ar": "وَقِيْلَ لِبَعْضِهِمْ: كَأَنَّ وَجْهَهُ الْقَمَرُ؟ فَقَالَ: بَلْ أَضْوَأُ مِنَ الْقَمَرِ إِذَا لَمْ يَحُلْ دُوْنَهُ الْغَمَامُ، قَدْ غَشِيَهُ الْجَلَالُ، وَانْتَهٰى إِلَيْهِ الْكَمَالُ", "lt": "Wa qîla liba‘dlihim: ka'anna wajhahul-qamar? faqâla: bal adlwa'u minal-qamari idzâ lam yaḥul dûnahul-ghamâm, qad ghasyiyahul-jalâl, wantahâ ilaihil-kamâl", "id": "Ditanyakan kepada salah seorang di antara mereka: Apakah wajahnya seperti bulan? Ia menjawab: Bahkan lebih terang daripada bulan ketika tidak tertutup awan. Keagungan meliputinya, dan kesempurnaan berpuncak padanya.", "no": 9},
{"ar": "قَالَ بَعْضُ وَاصِفِيْهِ: مَا رَأَيْتُ قَبْلَهُ وَلَا بَعْدَهُ مِثْلَهُ، فَيَعْجِزُ لِسَانُ الْبَلِيْغِ إِذَا أَرَادَ أَنْ يُحْصِيَ فَضْلَهُ", "lt": "Qâla ba‘dlu wâshifîh: mâ ra'aitu qablahû wa lâ ba‘dahû mitslah, faya‘jizu lisânul-balîghi idzâ arâda an yuḥshiya fadllah", "id": "Sebagian orang yang menyifatinya berkata: Aku tidak pernah melihat orang seperti beliau, baik sebelum maupun sesudahnya. Lisan orang yang fasih pun tak mampu bila hendak menghitung keutamaannya.", "no": 10},
{"ar": "فَسُبْحَانَ مَنْ خَصَّهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالْمَحَلِّ الْأَسْنٰى، وَأَسْرٰى بِهِ إِلَى قَابِ قَوْسَيْنِ أَوْ أَدْنٰى، وَأَيَّدَهُ بِالْمُعْجِزَاتِ الَّتِيْ لَا تُحْصٰى، وَأَوْفَاهُ مِنْ خِصَالِ الْكَمَالِ مَا يَجِلُّ أَنْ يُسْتَقْصٰى", "lt": "Fasubḥâna man khash-shahû shallallâhu ‘alaihi wa sallama bil-maḥallil-asnâ, wa asrâ bihî ilâ qâba qausaini au adnâ, wa ayyadahû bil-mu‘jizâtil-latî lâ tuḥshâ, wa aufâhu min khishâlil-kamâli mâ yajillu an yustaqshâ", "id": "Maha Suci (Allah) yang mengistimewakan beliau ﷺ dengan kedudukan yang paling luhur, memperjalankannya hingga jarak dua busur panah atau lebih dekat lagi, menguatkannya dengan mukjizat-mukjizat yang tak terhitung, dan menyempurnakan baginya sifat-sifat kesempurnaan yang terlalu agung untuk dihitung.", "no": 11},
{"ar": "وَأَعْطَاهُ خَمْسًا لَمْ يُعْطِهِنَّ أَحَدًا قَبْلَهُ، وَآتَاهُ جَوَامِعَ الْكَلِمِ فَلَمْ يُدْرِكْ أَحَدٌ فَضْلَهُ، وَكَانَ لَهُ فِيْ كُلِّ مَقَامٍ عِنْدَهُ مَقَالٌ، وَلِكُلِّ كَمَالٍ مِنْهُ كَمَالٌ، لَا يَحُوْرُ فِيْ سُؤَالٍ وَلَا جَوَابٍ، وَلَا يَجُوْلُ لِسَانُهُ إِلَّا فِيْ صَوَابٍ", "lt": "Wa a‘ṭâhu khamsan lam yu‘ṭihinna aḥadan qablah, wa âtâhu jawâmi‘al-kalimi falam yudrik aḥadun fadllah, wa kâna lahû fî kulli maqâmin ‘indahû maqâl, wa likulli kamâlin minhu kamâl, lâ yaḥûru fî su'âlin wa lâ jawâb, wa lâ yajûlu lisânuhû illâ fî shawâb", "id": "Allah memberinya lima keistimewaan yang tidak diberikan kepada seorang pun sebelumnya, dan memberinya kalimat yang singkat namun padat makna, sehingga tak seorang pun dapat menyamai keutamaannya. Dalam setiap keadaan beliau memiliki ucapan yang tepat, dan bagi setiap kesempurnaan ada kesempurnaan darinya. Beliau tidak pernah bingung dalam bertanya maupun menjawab, dan lisannya tidak berucap kecuali yang benar.", "no": 12},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 13},
{"ar": "وَمَا عَسٰى أَنْ يُقَالَ فِيْمَنْ وَصَفَهُ الْقُرْآنُ، وَأَعْرَبَ عَنْ فَضَائِلِهِ التَّوْرَاةُ وَالْإِنْجِيْلُ وَالزَّبُوْرُ وَالْفُرْقَانُ، وَجَمَعَ اللهُ لَهُ بَيْنَ رُؤْيَتِهِ وَكَلَامِهِ", "lt": "Wa mâ ‘asâ an yuqâla fî man washafahul-qur'ân, wa a‘raba ‘an fadlâ'ilihit-taurâtu wal-injîlu waz-zabûru wal-furqân, wa jama‘allâhu lahû baina ru'yatihî wa kalâmih", "id": "Apa lagi yang dapat dikatakan tentang seseorang yang telah disifati oleh Al-Qur'an, yang keutamaannya telah dijelaskan oleh Taurat, Injil, Zabur, dan Al-Furqan, dan yang telah Allah anugerahi kesempatan melihat-Nya dan berbicara dengan-Nya.", "no": 14},
{"ar": "وَقَرَنَ اسْمَهُ مَعَ اسْمِهِ تَنْبِيْهًا عَلَى عُلُوِّ مَقَامِهِ، وَجَعَلَهُ رَحْمَةً لِلْعَالَمِيْنَ وَنُوْرًا، وَمَلَأَ بِمَوْلِدِهِ الْقُلُوْبَ سُرُوْرًا", "lt": "Wa qaranas-mahû ma‘as-mihî tanbîhan ‘alâ ‘uluwwi maqâmih, wa ja‘alahû raḥmatan lil-‘âlamîna wa nûrâ, wa mala'a bimaulidihil-qulûba surûrâ", "id": "Allah menyandingkan namanya dengan nama-Nya sebagai tanda ketinggian kedudukannya, menjadikannya rahmat dan cahaya bagi seluruh alam, dan memenuhi hati dengan kegembiraan karena kelahirannya.", "no": 15},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 16}]},
{judul:"Ya Badra Timmin",isi:[
{"ar": "يَا بَدْرَ تِمٍّ حَازَ كُلَّ كَمَالِ ۞ مَاذَا يُعَبِّرُ عَنْ عُلَاكَ مَقَالِيْ", "lt": "Yâ badra timmin ḥâza kulla kamâli ۞ mâdzâ yu‘abbiru ‘an ‘ulâka maqâlî", "id": "Wahai purnama sempurna yang menghimpun segala kesempurnaan, bagaimana mungkin ucapanku mengungkapkan keluhuranmu?", "no": 1},
{"ar": "أَنْتَ الَّذِيْ أَشْرَقْتَ فِيْ أُفُقِ الْعُلَا ۞ فَمَحَوْتَ بِالْأَنْوَارِ كُلَّ ضَلَالِ", "lt": "Antal-ladzî asyraqta fî ufuqil-‘ulâ ۞ famaḥauta bil-anwâri kulla dlalâli", "id": "Engkaulah yang bersinar di ufuk keluhuran, dengan cahaya engkau hapuskan segala kesesatan.", "no": 2},
{"ar": "وَبِكَ اسْتَنَارَ الْكَوْنُ يَا عَلَمَ الْهُدٰى ۞ بِالنُّوْرِ وَالْإِنْعَامِ وَالْإِفْضَالِ", "lt": "Wa bikas-tanâral-kaunu yâ ‘alamal-hudâ ۞ bin-nûri wal-in‘âmi wal-ifdlâli", "id": "Denganmu alam semesta menjadi terang, wahai panji petunjuk, dengan cahaya, kenikmatan, dan karunia.", "no": 3},
{"ar": "صَلّٰى عَلَيْكَ اللهُ رَبِّيْ دَائِمًا ۞ أَبَدًا مَعَ الْإِبْكَارِ وَالْآصَالِ", "lt": "Shallâ ‘alaikallâhu rabbî dâ'iman ۞ abadan ma‘al-ibkâri wal-âshâli", "id": "Semoga Allah, Tuhanku, senantiasa melimpahkan shalawat kepadamu selama-lamanya, pagi dan petang.", "no": 4},
{"ar": "وَعَلٰى جَمِيْعِ الْآلِ وَالْأَصْحَابِ مَنْ ۞ قَدْ خَصَّهُمْ رَبُّ الْعُلَا بِكَمَالِ", "lt": "Wa ‘alâ jamî‘il-âli wal-ash-ḥâbi man ۞ qad khash-shahum rabbul-‘ulâ bikamâli", "id": "Juga kepada seluruh keluarga dan sahabat, yang telah diistimewakan oleh Tuhan Yang Mahatinggi dengan kesempurnaan.", "no": 5},
{"ar": "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", "lt": "Allâhumma shalli wa sallim wa bârik ‘alaih", "id": "Ya Allah, limpahkanlah shalawat, salam, dan keberkahan kepadanya.", "no": 6}]},
{judul:"Doa Maulid Diba'i",isi:[
{"ar": "بِسْمِ اللهِ الرَّحْمٰنِ الرَّحِيْمِ", "lt": "Bismillâhir-raḥmânir-raḥîm", "id": "Dengan nama Allah Yang Maha Pengasih lagi Maha Penyayang.", "no": 1},
{"ar": "اَلْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِيْنَ، اَللّٰهُمَّ صَلِّ وَسَلِّمْ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِهِ وَصَحْبِهِ أَجْمَعِيْنَ، جَعَلَنَا اللهُ وَإِيَّاكُمْ مِمَّنْ يَسْتَوْجِبُ شَفَاعَتَهُ، وَيَرْجُوْ رَحْمَتَهُ وَرَأْفَتَهُ", "lt": "Al-ḥamdu lillâhi rabbil-‘âlamîn, allâhumma shalli wa sallim ‘alâ sayyidinâ muḥammadin wa ‘alâ âlihî wa shaḥbihî ajma‘în, ja‘alanallâhu wa iyyâkum mimman yastaujibu syafâ‘atahû, wa yarjû raḥmatahû wa ra'fatah", "id": "Segala puji bagi Allah, Tuhan semesta alam. Ya Allah, limpahkanlah shalawat dan salam kepada junjungan kami Nabi Muhammad, keluarga, dan seluruh sahabatnya. Semoga Allah menjadikan kami dan kalian termasuk orang yang berhak mendapat syafaatnya, serta mengharapkan rahmat dan kasih sayangnya.", "no": 2},
{"ar": "اَللّٰهُمَّ بِحُرْمَةِ هٰذَا النَّبِيِّ الْكَرِيْمِ، وَآلِهِ وَأَصْحَابِهِ السَّالِكِيْنَ عَلَى مَنْهَجِهِ الْقَوِيْمِ، اجْعَلْنَا مِنْ خِيَارِ أُمَّتِهِ، وَاسْتُرْنَا بِذَيْلِ حُرْمَتِهِ، وَاحْشُرْنَا غَدًا فِيْ زُمْرَتِهِ", "lt": "Allâhumma biḥurmati hâdzan-nabiyyil-karîm, wa âlihî wa ash-ḥâbihis-sâlikîna ‘alâ manhajihil-qawîm, ij‘alnâ min khiyâri ummatih, wasturnâ bidzaili ḥurmatih, waḥsyurnâ ghadan fî zumratih", "id": "Ya Allah, demi kemuliaan Nabi yang mulia ini, keluarga dan para sahabatnya yang menempuh jalannya yang lurus, jadikanlah kami termasuk umatnya yang terbaik, tutupilah (aib) kami dengan ujung kehormatannya, dan kumpulkanlah kami kelak dalam rombongannya.", "no": 3},
{"ar": "وَاسْتَعْمِلْ أَلْسِنَتَنَا فِيْ مَدْحِهِ وَنُصْرَتِهِ، وَأَحْيِنَا مُتَمَسِّكِيْنَ بِسُنَّتِهِ وَطَاعَتِهِ، وَأَمِتْنَا عَلَى حُبِّهِ وَجَمَاعَتِهِ", "lt": "Wasta‘mil alsinatanâ fî madḥihî wa nushratih, wa aḥyinâ mutamassikîna bisunnatihî wa ṭâ‘atih, wa amitnâ ‘alâ ḥubbihî wa jamâ‘atih", "id": "Gunakanlah lisan kami untuk memuji dan membelanya, hidupkanlah kami dalam keadaan berpegang teguh pada sunnah dan ketaatan kepadanya, dan matikanlah kami dalam keadaan mencintainya dan berada dalam jamaahnya.", "no": 4},
{"ar": "اَللّٰهُمَّ أَدْخِلْنَا مَعَهُ الْجَنَّةَ فَإِنَّهُ أَوَّلُ مَنْ يَدْخُلُهَا، وَأَنْزِلْنَا مَعَهُ فِيْ قُصُوْرِهَا فَإِنَّهُ أَوَّلُ مَنْ يَنْزِلُهَا، وَارْحَمْنَا يَوْمَ يَشْفَعُ لِلْخَلَائِقِ فَتَرْحَمُهَا", "lt": "Allâhumma adkhilnâ ma‘ahul-jannata fa'innahû awwalu man yadkhuluhâ, wa anzilnâ ma‘ahû fî qushûrihâ fa'innahû awwalu man yanziluhâ, warḥamnâ yauma yasyfa‘u lil-khalâ'iqi fataraḥmuhâ", "id": "Ya Allah, masukkanlah kami ke surga bersamanya, karena beliau adalah orang pertama yang memasukinya; tempatkanlah kami bersamanya di istana-istananya, karena beliau orang pertama yang menempatinya; dan rahmatilah kami pada hari beliau memberi syafaat kepada para makhluk lalu Engkau merahmati mereka.", "no": 5},
{"ar": "اَللّٰهُمَّ ارْزُقْنَا زِيَارَتَهُ فِيْ كُلِّ سَنَةٍ، وَلَا تَجْعَلْنَا مِنَ الْغَافِلِيْنَ عَنْكَ وَلَا عَنْهُ قَدْرَ سِنَةٍ", "lt": "Allâhummar-zuqnâ ziyâratahû fî kulli sanah, wa lâ taj‘alnâ minal-ghâfilîna ‘anka wa lâ ‘anhu qadra sinah", "id": "Ya Allah, karuniakanlah kepada kami kesempatan berziarah kepadanya setiap tahun, dan janganlah Engkau jadikan kami termasuk orang yang lalai dari-Mu dan darinya walau sekejap kantuk.", "no": 6},
{"ar": "اَللّٰهُمَّ لَا تَجْعَلْ فِيْ مَجْلِسِنَا هٰذَا أَحَدًا إِلَّا غَسَلْتَ بِمَاءِ التَّوْبَةِ ذُنُوْبَهُ، وَسَتَرْتَ بِرِدَاءِ الْمَغْفِرَةِ عُيُوْبَهُ", "lt": "Allâhumma lâ taj‘al fî majlisinâ hâdzâ aḥadan illâ ghasalta bimâ'it-taubati dzunûbah, wa satarta biridâ'il-maghfirati ‘uyûbah", "id": "Ya Allah, janganlah Engkau biarkan seorang pun dalam majelis kami ini kecuali Engkau basuh dosa-dosanya dengan air tobat, dan Engkau tutup aib-aibnya dengan selendang ampunan.", "no": 7},
{"ar": "اَللّٰهُمَّ إِنَّهُ كَانَ مَعَنَا فِي السَّنَةِ الْمَاضِيَةِ إِخْوَانٌ مَنَعَهُمُ الْقَضَاءُ عَنِ الْوُصُوْلِ إِلَى مِثْلِهَا، فَلَا تَحْرِمْهُمْ مِنْ ثَوَابِ هٰذِهِ السَّاعَةِ وَفَضْلِهَا", "lt": "Allâhumma innahû kâna ma‘anâ fis-sanatil-mâdliyati ikhwânun mana‘ahumul-qadlâ'u ‘anil-wushûli ilâ mitslihâ, falâ taḥrimhum min tsawâbi hâdzihis-sâ‘ati wa fadllihâ", "id": "Ya Allah, pada tahun yang lalu ada saudara-saudara kami yang bersama kami, namun takdir menghalangi mereka untuk hadir pada majelis seperti ini; maka janganlah Engkau halangi mereka dari pahala dan keutamaan saat ini.", "no": 8},
{"ar": "اَللّٰهُمَّ ارْحَمْنَا إِذَا صِرْنَا مِنْ أَصْحَابِ الْقُبُوْرِ، وَوَفِّقْنَا لِعَمَلٍ صَالِحٍ يَبْقٰى سَنَاهُ عَلَى مَمَرِّ الدُّهُوْرِ", "lt": "Allâhummar-ḥamnâ idzâ shirnâ min ash-ḥâbil-qubûr, wa waffiqnâ li‘amalin shâliḥin yabqâ sanâhu ‘alâ mamarrid-duhûr", "id": "Ya Allah, rahmatilah kami apabila kami telah menjadi penghuni kubur, dan berilah kami taufik untuk beramal saleh yang cahayanya tetap ada sepanjang masa.", "no": 9},
{"ar": "اَللّٰهُمَّ اجْعَلْنَا لِآلَائِكَ ذَاكِرِيْنَ، وَلِنَعْمَائِكَ شَاكِرِيْنَ، وَلِيَوْمِ لِقَائِكَ مِنَ الذَّاكِرِيْنَ، وَأَحْيِنَا بِطَاعَتِكَ مَشْغُوْلِيْنَ، وَإِذَا تَوَفَّيْتَنَا فَتَوَفَّنَا غَيْرَ مَفْتُوْنِيْنَ وَلَا مَخْذُوْلِيْنَ، وَاخْتِمْ لَنَا مِنْكَ بِخَيْرٍ أَجْمَعِيْنَ", "lt": "Allâhummaj‘alnâ li'âlâ'ika dzâkirîn, wa lina‘mâ'ika syâkirîn, wa liyaumi liqâ'ika minadz-dzâkirîn, wa aḥyinâ biṭâ‘atika masyghûlîn, wa idzâ tawaffaitanâ fatawaffanâ ghaira maftûnîna wa lâ makhdzûlîn, wakhtim lanâ minka bikhairin ajma‘în", "id": "Ya Allah, jadikanlah kami orang-orang yang senantiasa mengingat nikmat-nikmat-Mu, mensyukuri karunia-karunia-Mu, dan mengingat hari pertemuan dengan-Mu. Hidupkanlah kami dalam keadaan sibuk dengan ketaatan kepada-Mu. Apabila Engkau mewafatkan kami, wafatkanlah kami tanpa tertimpa fitnah dan tanpa terhina, dan akhirilah hidup kami semua dengan kebaikan dari-Mu.", "no": 10},
{"ar": "اَللّٰهُمَّ اكْفِنَا شَرَّ الظَّالِمِيْنَ، وَاجْعَلْنَا مِنْ فِتْنَةِ هٰذِهِ الدُّنْيَا سَالِمِيْنَ", "lt": "Allâhummakfinâ syarradh-dhâlimîn, waj‘alnâ min fitnati hâdzihid-dunyâ sâlimîn", "id": "Ya Allah, lindungilah kami dari kejahatan orang-orang zalim, dan jadikanlah kami selamat dari fitnah dunia ini.", "no": 11},
{"ar": "اَللّٰهُمَّ اجْعَلْ هٰذَا الرَّسُوْلَ الْكَرِيْمَ لَنَا شَفِيْعًا، وَارْزُقْنَا بِهِ يَوْمَ الْقِيَامَةِ مَقَامًا رَفِيْعًا", "lt": "Allâhummaj‘al hâdzar-rasûlal-karîma lanâ syafî‘â, warzuqnâ bihî yaumal-qiyâmati maqâman rafî‘â", "id": "Ya Allah, jadikanlah Rasul yang mulia ini pemberi syafaat bagi kami, dan karuniakanlah kepada kami berkat beliau kedudukan yang tinggi pada hari kiamat.", "no": 12},
{"ar": "اَللّٰهُمَّ اسْقِنَا مِنْ حَوْضِ نَبِيِّكَ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ شَرْبَةً هَنِيْئَةً لَا نَظْمَأُ بَعْدَهَا أَبَدًا، وَاحْشُرْنَا تَحْتَ لِوَائِهِ غَدًا", "lt": "Allâhummasqinâ min ḥaudli nabiyyika muḥammadin shallallâhu ‘alaihi wa sallama syarbatan hanî'atan lâ nadhma'u ba‘dahâ abadâ, waḥsyurnâ taḥta liwâ'ihî ghadâ", "id": "Ya Allah, berilah kami minum dari telaga Nabi-Mu, Muhammad ﷺ, seteguk minuman yang menyegarkan, yang setelahnya kami tidak akan haus selamanya, dan kumpulkanlah kami kelak di bawah panjinya.", "no": 13},
{"ar": "اَللّٰهُمَّ اغْفِرْ لَنَا بِهِ وَلِآبَائِنَا وَلِأُمَّهَاتِنَا وَلِمَشَايِخِنَا وَلِمُعَلِّمِيْنَا وَذَوِي الْحُقُوْقِ عَلَيْنَا، وَلِجَمِيْعِ الْمُؤْمِنِيْنَ وَالْمُؤْمِنَاتِ وَالْمُسْلِمِيْنَ وَالْمُسْلِمَاتِ، الْأَحْيَاءِ مِنْهُمْ وَالْأَمْوَاتِ", "lt": "Allâhummaghfir lanâ bihî wa li'âbâ'inâ wa li'ummahâtinâ wa limasyâyikhinâ wa limu‘allimînâ wa dzawil-ḥuqûqi ‘alainâ, wa lijamî‘il-mu'minîna wal-mu'minâti wal-muslimîna wal-muslimât, al-aḥyâ'i minhum wal-amwât", "id": "Ya Allah, ampunilah kami berkat beliau, juga ayah-ayah kami, ibu-ibu kami, para guru dan pengajar kami, orang-orang yang memiliki hak atas kami, serta seluruh mukminin dan mukminat, muslimin dan muslimat, baik yang masih hidup maupun yang telah wafat.", "no": 14},
{"ar": "إِنَّكَ مُجِيْبُ الدَّعَوَاتِ، وَقَاضِي الْحَاجَاتِ، وَغَافِرُ الذُّنُوْبِ وَالْخَطِيْئَاتِ، يَا أَرْحَمَ الرَّاحِمِيْنَ", "lt": "Innaka mujîbud-da‘awât, wa qâdlil-ḥâjât, wa ghâfirudz-dzunûbi wal-khaṭî'ât, yâ arḥamar-râḥimîn", "id": "Sesungguhnya Engkau Maha Mengabulkan doa-doa, Maha Memenuhi segala hajat, dan Maha Mengampuni dosa-dosa dan kesalahan, wahai Yang Maha Pengasih di antara para pengasih.", "no": 15},
{"ar": "وَصَلَّى اللهُ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِهِ وَصَحْبِهِ وَسَلَّمَ، سُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُوْنَ، وَسَلَامٌ عَلَى الْمُرْسَلِيْنَ، وَالْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِيْنَ", "lt": "Wa shallallâhu ‘alâ sayyidinâ muḥammadin wa ‘alâ âlihî wa shaḥbihî wa sallam, subḥâna rabbika rabbil-‘izzati ‘ammâ yashifûn, wa salâmun ‘alal-mursalîn, wal-ḥamdu lillâhi rabbil-‘âlamîn", "id": "Semoga Allah melimpahkan shalawat dan salam kepada junjungan kami Nabi Muhammad, keluarga, dan para sahabatnya. Maha Suci Tuhanmu, Tuhan Yang Mahaperkasa, dari apa yang mereka sifatkan. Salam sejahtera bagi para rasul, dan segala puji bagi Allah, Tuhan semesta alam.", "no": 16}]}]});
